-- MakeMeMeals — PostgreSQL Schema
-- Run this in Railway: open your Postgres service > Query tab, paste and run

CREATE TABLE IF NOT EXISTS users (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  clerk_id      TEXT UNIQUE NOT NULL,
  email         TEXT NOT NULL,
  subscription  TEXT DEFAULT 'free',   -- free | active | cancelled
  free_weeks    INT DEFAULT 0,
  created_at    TIMESTAMPTZ DEFAULT NOW()
);

-- Guest users (no Clerk account)
CREATE TABLE IF NOT EXISTS guest_sessions (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_key TEXT UNIQUE NOT NULL,
  used        BOOLEAN DEFAULT FALSE,
  created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS preferences (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          UUID REFERENCES users(id) ON DELETE CASCADE,
  servings         INT DEFAULT 4,
  picky_eaters     BOOLEAN DEFAULT FALSE,
  keep_mild        BOOLEAN DEFAULT FALSE,
  meat_free        BOOLEAN DEFAULT FALSE,
  gluten_free      BOOLEAN DEFAULT FALSE,
  dairy_free       BOOLEAN DEFAULT FALSE,
  thirty_min_max   BOOLEAN DEFAULT FALSE,
  high_protein     BOOLEAN DEFAULT FALSE,
  low_waste        BOOLEAN DEFAULT FALSE,
  budget           INT DEFAULT 100,
  store            TEXT DEFAULT 'Any',
  UNIQUE (user_id)
);

CREATE TABLE IF NOT EXISTS meal_plans (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID REFERENCES users(id) ON DELETE CASCADE,
  is_guest    BOOLEAN DEFAULT FALSE,
  days        INT NOT NULL,
  week_of     DATE,
  created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS meals (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id         UUID REFERENCES meal_plans(id) ON DELETE CASCADE,
  day_number      INT NOT NULL,
  name            TEXT NOT NULL,
  description     TEXT,
  prep_minutes    INT,
  difficulty      TEXT,
  ingredients     JSONB,
  steps           JSONB,
  estimated_cost  NUMERIC(6,2),
  emoji           TEXT
);

CREATE TABLE IF NOT EXISTS grocery_lists (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id         UUID REFERENCES meal_plans(id) ON DELETE CASCADE,
  items           JSONB,
  estimated_total NUMERIC(8,2),
  UNIQUE (plan_id)
);

-- Indexes for common lookups
CREATE INDEX IF NOT EXISTS idx_users_clerk_id    ON users(clerk_id);
CREATE INDEX IF NOT EXISTS idx_plans_user_id     ON meal_plans(user_id);
CREATE INDEX IF NOT EXISTS idx_meals_plan_id     ON meals(plan_id);
CREATE INDEX IF NOT EXISTS idx_grocery_plan_id   ON grocery_lists(plan_id);
CREATE INDEX IF NOT EXISTS idx_prefs_user_id     ON preferences(user_id);
CREATE INDEX IF NOT EXISTS idx_guest_key         ON guest_sessions(session_key);

-- Add new columns to existing tables (safe to run on existing DBs)
ALTER TABLE preferences ADD COLUMN IF NOT EXISTS budget       INT     DEFAULT 100;
ALTER TABLE preferences ADD COLUMN IF NOT EXISTS store        TEXT    DEFAULT 'Any';
ALTER TABLE preferences ADD COLUMN IF NOT EXISTS high_protein BOOLEAN DEFAULT FALSE;
ALTER TABLE preferences ADD COLUMN IF NOT EXISTS low_waste    BOOLEAN DEFAULT FALSE;
ALTER TABLE meal_plans  ADD COLUMN IF NOT EXISTS is_guest     BOOLEAN DEFAULT FALSE;

ALTER TABLE users ADD COLUMN IF NOT EXISTS stripe_customer_id     TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS stripe_subscription_id TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS promo_code             TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS promo_redeemed_at      TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN IF NOT EXISTS free_plans_used        INT DEFAULT 0;

-- Recipe card system
ALTER TABLE meals ADD COLUMN IF NOT EXISTS cuisine      TEXT;
ALTER TABLE meals ADD COLUMN IF NOT EXISTS pexels_query TEXT;
ALTER TABLE meals ADD COLUMN IF NOT EXISTS chef_tip     TEXT;
ALTER TABLE meals ADD COLUMN IF NOT EXISTS inspired_by  TEXT;
ALTER TABLE meal_plans ADD COLUMN IF NOT EXISTS meal_emojis JSONB;

-- Admin flag
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_admin BOOLEAN DEFAULT FALSE;

-- Pantry / fridge tracker
CREATE TABLE IF NOT EXISTS pantry_items (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID REFERENCES users(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  quantity    NUMERIC(10,2),
  unit        TEXT,
  category    TEXT DEFAULT 'other',
  expires_at  DATE,
  added_at    TIMESTAMPTZ DEFAULT NOW(),
  updated_at  TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pantry_user_id ON pantry_items(user_id);

-- Uploaded recipe cards (admin-curated + user-submitted)
CREATE TABLE IF NOT EXISTS recipe_cards (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID REFERENCES users(id) ON DELETE CASCADE,
  source       TEXT DEFAULT 'user',
  image_url    TEXT,
  name         TEXT,
  cuisine      TEXT,
  description  TEXT,
  ingredients  JSONB DEFAULT '[]',
  steps        JSONB DEFAULT '[]',
  prep_minutes INT,
  servings     INT,
  chef_tip     TEXT,
  approved     BOOLEAN DEFAULT FALSE,
  created_at   TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_recipe_cards_user_id  ON recipe_cards(user_id);
CREATE INDEX IF NOT EXISTS idx_recipe_cards_approved ON recipe_cards(approved);

-- Coupons
CREATE TABLE IF NOT EXISTS coupons (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  store       TEXT NOT NULL DEFAULT 'all',
  brand       TEXT,
  product     TEXT NOT NULL,
  description TEXT,
  discount    TEXT,
  category    TEXT,
  image_emoji TEXT DEFAULT '🏷️',
  valid_until DATE,
  keywords    TEXT[] DEFAULT '{}',
  created_at  TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_coupons_store ON coupons(store);

-- Patch existing recipe_cards table with missing columns
ALTER TABLE recipe_cards ADD COLUMN IF NOT EXISTS estimated_cost NUMERIC(6,2);
ALTER TABLE recipe_cards ADD COLUMN IF NOT EXISTS servings       INT;
ALTER TABLE recipe_cards ADD COLUMN IF NOT EXISTS inspired_by    TEXT;

-- Refresh admin recipe cards on every deploy
DELETE FROM recipe_cards WHERE source = 'admin';
INSERT INTO recipe_cards
  (source, image_url, name, cuisine, description, ingredients, steps, prep_minutes, servings, estimated_cost, chef_tip, inspired_by, approved)
VALUES
  ('admin', NULL, 'Shrimp Fra Diavolo', 'italian', 'A fiery Italian-American classic — seared shrimp in a spicy tomato sauce tossed with al dente linguine. Restaurant quality, done in 25 minutes.', '[{"name": "large shrimp", "quantity": "1", "unit": "lb"}, {"name": "linguine", "quantity": "16", "unit": "oz"}, {"name": "crushed tomatoes", "quantity": "28", "unit": "oz"}, {"name": "Pinot Grigio white wine", "quantity": "0.5", "unit": "cup"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "red pepper flakes", "quantity": "1", "unit": "tsp"}, {"name": "fresh parsley chopped", "quantity": "0.25", "unit": "cup"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "butter", "quantity": "2", "unit": "tbsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Cook linguine in heavily salted boiling water until al dente.", "Reserve 1 cup pasta water, then drain and set aside.", "Season shrimp generously with salt and pepper.", "Heat olive oil and 1 tbsp butter in a large skillet over high heat.", "Add shrimp and sear 1-2 min per side until pink. Remove and set aside.", "Add garlic and red pepper flakes to the same pan. Saute 30 seconds.", "Pour in white wine, scraping up any browned bits. Reduce by half, about 2 min.", "Add crushed tomatoes. Simmer 5 minutes until slightly thickened.", "Return shrimp to sauce. Add pasta and toss, using pasta water to loosen as needed. Stir in remaining butter and parsley. Serve immediately."]', 25, 2, 14.00, 'Save your pasta water — it''s the secret to a silky, restaurant-quality sauce.', 'Italian coastal tradition', TRUE),
  ('admin', NULL, 'Tuscan Ribeye with Rosemary Butter', 'steakhouse', 'A butter-basted bone-in ribeye with fragrant rosemary and golden baby potatoes — inspired by Carrabba''s signature Italian steakhouse style.', '[{"name": "bone-in ribeye steaks", "quantity": "2", "unit": "steaks"}, {"name": "fresh rosemary", "quantity": "2", "unit": "sprigs"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "minced garlic", "quantity": "2", "unit": "cloves"}, {"name": "baby gold potatoes", "quantity": "1", "unit": "lb"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Take steaks out of the fridge 30 minutes before cooking to come to room temperature.", "Boil or roast baby potatoes until golden and tender. Season with salt and olive oil.", "Preheat a heavy cast iron skillet over high heat until smoking.", "Pat steaks dry and season generously with salt and pepper on both sides.", "Add olive oil to skillet. Sear steaks 3-4 minutes per side without moving.", "Reduce heat to medium. Add butter, garlic, and rosemary.", "Tilt the pan and use a spoon to continuously baste the steaks with the foamy butter for 1-2 minutes.", "Cook to your desired doneness (125F rare, 135F medium-rare, 145F medium).", "Transfer steaks to a cutting board. Rest 5 full minutes before slicing. Serve with potatoes."]', 25, 2, 18.00, 'Let the steak rest 5 full minutes before cutting — this is non-negotiable. Cutting too early loses all the juices.', 'Carrabba''s', TRUE),
  ('admin', NULL, 'Crispy Parmesan Chicken with Garlic Potatoes', 'italian', 'Crispy parmesan-coated chicken bakes until golden while garlicky roasted potatoes crisp in the oven.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "parmesan cheese", "quantity": "1", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1", "unit": "cup"}, {"name": "eggs", "quantity": "2", "unit": ""}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}, {"name": "garlic powder", "quantity": "2", "unit": "tsp"}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "parsley", "quantity": "2", "unit": "tbsp"}]', '["Preheat oven to 425F and line a sheet pan.", "Toss diced potatoes with oil and garlic powder; roast 15 minutes.", "Coat chicken in egg, parmesan, and breadcrumbs.", "Add chicken beside potatoes and bake 20-22 minutes until 165F.", "Sprinkle parsley and serve hot."]', 45, 4, 17.00, 'Add parmesan directly onto the potatoes during the last 8 minutes for crisp edges.', 'Inspired by Carrabba''s', TRUE),
  ('admin', NULL, 'Chipotle Chicken Burrito Bowls', 'mexican', 'Smoky chicken rice bowls layered with corn, beans, and creamy lime crema bring takeout flavor home fast.', '[{"name": "chicken thighs boneless skinless", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "canned black beans", "quantity": "1", "unit": "can"}, {"name": "frozen corn", "quantity": "1", "unit": "bag"}, {"name": "sour cream", "quantity": "1", "unit": "cup"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "taco seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "shredded cheddar", "quantity": "1", "unit": "cup"}]', '["Cook rice according to package.", "Season chicken with taco seasoning and cook in skillet 6-8 minutes per side.", "Heat beans and corn.", "Mix sour cream with lime juice.", "Slice chicken and assemble bowls."]', 30, 4, 14.00, 'Char frozen corn in a skillet for 3 minutes to mimic restaurant flavor.', 'Inspired by Chipotle', TRUE),
  ('admin', NULL, 'Honey Garlic Beef Stir Fry', 'asian', 'Tender strips of beef coated in sticky garlic sauce pair perfectly with crisp vegetables over rice.', '[{"name": "flank steak", "quantity": "1.5", "unit": "lbs"}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "carrots", "quantity": "2", "unit": ""}, {"name": "soy sauce", "quantity": "1/3", "unit": "cup"}, {"name": "honey", "quantity": "3", "unit": "tbsp"}, {"name": "garlic cloves", "quantity": "4", "unit": ""}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "sesame oil", "quantity": "1", "unit": "tbsp"}]', '["Slice beef thinly.", "Cook rice.", "Stir fry beef over high heat for 3-4 minutes and remove.", "Cook vegetables until tender-crisp.", "Combine soy sauce, honey, garlic, and sesame oil.", "Return beef to skillet and toss in sauce."]', 30, 4, 21.00, 'Freeze steak for 20 minutes before slicing for thinner restaurant-style strips.', 'Inspired by PF Chang''s', TRUE),
  ('admin', NULL, 'Greek Lemon Chicken Pitas', 'mediterranean', 'Bright lemony chicken tucked into warm pita with crisp vegetables and creamy yogurt sauce tastes fresh yet comforting.', '[{"name": "chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "pita bread", "quantity": "8", "unit": ""}, {"name": "cucumber", "quantity": "1", "unit": ""}, {"name": "tomatoes", "quantity": "2", "unit": ""}, {"name": "plain Greek yogurt", "quantity": "1", "unit": "cup"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "lettuce", "quantity": "1", "unit": "head"}]', '["Season chicken with lemon juice, garlic powder, salt, and pepper.", "Pan sear 5-6 minutes each side.", "Mix yogurt with lemon juice.", "Warm pita.", "Fill pita with vegetables, chicken, and yogurt sauce."]', 30, 4, 15.00, 'Warm pitas directly over a burner flame for 10 seconds for restaurant texture.', 'Inspired by Greek taverna tradition', TRUE),
  ('admin', NULL, 'Smothered Country Pork Chops', 'southern', 'Tender pork chops smothered in savory onion gravy feel like comfort food straight from grandma''s kitchen.', '[{"name": "pork chops", "quantity": "2", "unit": "lbs"}, {"name": "yellow onion", "quantity": "1", "unit": ""}, {"name": "chicken broth", "quantity": "2", "unit": "cups"}, {"name": "flour", "quantity": "3", "unit": "tbsp"}, {"name": "potatoes", "quantity": "2", "unit": "lbs"}, {"name": "milk", "quantity": "1", "unit": "cup"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}]', '["Boil potatoes until soft.", "Season and sear pork chops.", "Cook onions until caramelized.", "Add flour and broth to create gravy.", "Simmer pork chops in gravy 15 minutes.", "Mash potatoes with butter and milk."]', 50, 4, 18.00, 'Let pork chops rest 5 minutes before simmering to keep them juicy.', 'Inspired by Cracker Barrel', TRUE),
  ('admin', NULL, 'Creamy Tomato Basil Pasta', 'italian', 'Rich tomato cream sauce coats pasta with melty parmesan and fresh basil in every bite.', '[{"name": "penne pasta", "quantity": "1", "unit": "lb"}, {"name": "crushed tomatoes", "quantity": "1", "unit": "can"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "parmesan cheese", "quantity": "1", "unit": "cup"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "basil", "quantity": "1", "unit": "bunch"}]', '["Boil pasta.", "Saute garlic in oil.", "Add tomatoes and simmer.", "Stir in cream and parmesan.", "Toss pasta in sauce and garnish with basil."]', 30, 4, 11.00, 'Save 1/2 cup pasta water to make sauce cling better.', 'Inspired by Olive Garden', TRUE),
  ('admin', NULL, 'Sweet Chili Salmon Bowls', 'seafood', 'Flaky glazed salmon served over rice with crisp vegetables feels restaurant fancy without much effort.', '[{"name": "salmon fillets", "quantity": "2", "unit": "lbs"}, {"name": "sweet chili sauce", "quantity": "1/2", "unit": "cup"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "cucumber", "quantity": "1", "unit": ""}, {"name": "carrots", "quantity": "2", "unit": ""}, {"name": "broccoli florets", "quantity": "1", "unit": "bag"}]', '["Roast salmon at 400F for 15 minutes.", "Brush with sweet chili sauce halfway through.", "Steam vegetables.", "Cook rice.", "Assemble bowls."]', 30, 4, 24.00, 'Pat salmon dry before roasting for better caramelization.', 'Inspired by Bonefish Grill', TRUE),
  ('admin', NULL, 'Thai Peanut Chicken Noodles', 'thai', 'Creamy peanut sauce wraps around noodles and juicy chicken with just enough sweetness and spice.', '[{"name": "chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "spaghetti noodles", "quantity": "1", "unit": "lb"}, {"name": "peanut butter", "quantity": "1/3", "unit": "cup"}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "honey", "quantity": "2", "unit": "tbsp"}, {"name": "shredded carrots", "quantity": "2", "unit": ""}, {"name": "green onions", "quantity": "4", "unit": ""}]', '["Cook noodles.", "Pan cook chicken and slice.", "Mix peanut butter, soy sauce, honey, and warm water.", "Toss noodles in sauce.", "Top with chicken and vegetables."]', 35, 4, 15.00, 'Add a splash of pasta water to loosen peanut sauce if thick.', 'Inspired by Thai street food tradition', TRUE),
  ('admin', NULL, 'Steakhouse Garlic Butter Burgers', 'steakhouse', 'Juicy burgers brushed with garlic butter and topped with melty cheese feel like steakhouse comfort at home.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "burger buns", "quantity": "4", "unit": ""}, {"name": "cheddar cheese slices", "quantity": "4", "unit": ""}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "2", "unit": "tsp"}, {"name": "ketchup", "quantity": "1/4", "unit": "cup"}]', '["Preheat oven to 425F and cut potatoes into fries.", "Toss fries with oil, salt, pepper, and garlic powder; bake 30 minutes.", "Form burger patties and season generously.", "Cook burgers in skillet 4-5 minutes per side.", "Melt cheese over patties and brush with garlic butter.", "Serve on toasted buns with fries."]', 35, 4, 19.00, 'Press a small thumbprint in burger centers before cooking to keep them flat.', 'Inspired by LongHorn Steakhouse', TRUE),
  ('admin', NULL, 'Shrimp Street Tacos with Lime Slaw', 'latin', 'Tender shrimp tossed in smoky spices tucked into warm tortillas with crunchy lime slaw taste bright and fresh.', '[{"name": "shrimp peeled and deveined", "quantity": "1.5", "unit": "lbs"}, {"name": "corn tortillas", "quantity": "8", "unit": ""}, {"name": "shredded cabbage", "quantity": "1", "unit": "bag"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "sour cream", "quantity": "1/2", "unit": "cup"}, {"name": "chili powder", "quantity": "2", "unit": "tsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Toss shrimp with chili powder, garlic powder, salt, and oil.", "Cook shrimp in skillet for 2-3 minutes per side.", "Mix cabbage with lime juice and sour cream.", "Warm tortillas in skillet.", "Fill tortillas with shrimp and slaw."]', 25, 4, 18.00, 'Remove shrimp as soon as they curl into a loose C shape — they keep cooking off heat.', 'Inspired by Bahama Breeze', TRUE),
  ('admin', NULL, 'Cheeseburger Mac Skillet', 'american', 'Creamy cheesy pasta meets savory ground beef in a one-pan dinner kids devour.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "elbow pasta", "quantity": "1", "unit": "lb"}, {"name": "shredded cheddar cheese", "quantity": "2", "unit": "cups"}, {"name": "milk", "quantity": "1", "unit": "cup"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "beef broth", "quantity": "3", "unit": "cups"}]', '["Brown beef and onion in a large skillet.", "Add broth and pasta directly to skillet.", "Simmer covered until pasta softens.", "Stir in cheese and milk.", "Serve immediately."]', 30, 5, 15.00, 'Add cheese gradually to avoid clumping.', 'Inspired by Applebee''s', TRUE),
  ('admin', NULL, 'Tuscan Cream Chicken Soup', 'italian', 'Creamy broth loaded with tender chicken, potatoes, and herbs tastes deeply comforting on busy nights.', '[{"name": "chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "potatoes", "quantity": "1.5", "unit": "lbs"}, {"name": "baby spinach", "quantity": "1", "unit": "bag"}, {"name": "chicken broth", "quantity": "6", "unit": "cups"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "onion", "quantity": "1", "unit": ""}]', '["Saute onion and garlic in pot.", "Add chicken broth and potatoes; simmer 15 minutes.", "Add chicken pieces and cook until done.", "Stir in cream and spinach.", "Simmer 5 more minutes and season."]', 45, 5, 16.25, 'Add spinach at the end so it stays bright green instead of dull.', 'Inspired by Tuscan farmhouse tradition', TRUE),
  ('admin', NULL, 'Korean BBQ Beef Bowls', 'korean', 'Sweet soy beef piled over rice with crisp cucumbers delivers big flavor fast.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "soy sauce", "quantity": "1/4", "unit": "cup"}, {"name": "brown sugar", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "cucumber", "quantity": "1", "unit": ""}, {"name": "sesame oil", "quantity": "1", "unit": "tsp"}]', '["Cook rice.", "Brown beef with garlic.", "Add soy sauce, sugar, and sesame oil.", "Simmer until glossy.", "Serve over rice with cucumber slices."]', 25, 4, 19.00, 'Add a splash of water to thin sauce if it reduces too quickly.', 'Inspired by Korean BBQ tradition', TRUE),
  ('admin', NULL, 'Lemon Herb Baked Cod', 'seafood', 'Flaky cod baked with lemon and herbs tastes light but deeply satisfying. Served with roasted vegetables.', '[{"name": "cod fillets", "quantity": "2", "unit": "lbs"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "broccoli florets", "quantity": "1", "unit": "bag"}, {"name": "carrots", "quantity": "3", "unit": ""}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Heat oven to 400F.", "Toss vegetables with oil and roast 20 minutes.", "Place cod on sheet pan with lemon slices and seasoning.", "Bake cod for 12-15 minutes.", "Serve immediately."]', 30, 4, 22.00, 'Cod is done once it flakes easily with a fork — avoid overbaking.', 'Inspired by Legal Sea Foods', TRUE),
  ('admin', NULL, 'Loaded Chicken Quesadillas', 'mexican', 'Crispy cheesy quesadillas packed with seasoned chicken taste like restaurant appetizers turned dinner.', '[{"name": "chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "flour tortillas", "quantity": "8", "unit": ""}, {"name": "shredded Mexican cheese", "quantity": "2", "unit": "cups"}, {"name": "bell peppers", "quantity": "2", "unit": ""}, {"name": "taco seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "sour cream", "quantity": "1", "unit": "cup"}]', '["Cook chicken with taco seasoning.", "Saute peppers.", "Layer tortilla with cheese, chicken, and peppers.", "Fold and crisp in skillet until golden.", "Slice and serve."]', 30, 4, 14.00, 'Cover skillet briefly while cooking to melt cheese faster.', 'Inspired by Chili''s', TRUE),
  ('admin', NULL, 'Garlic Butter Steak Bites and Potatoes', 'steakhouse', 'Juicy steak bites tossed in garlic butter with crispy potatoes feel indulgent and hearty.', '[{"name": "sirloin steak", "quantity": "2", "unit": "lbs"}, {"name": "potatoes", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh parsley", "quantity": "2", "unit": "tbsp"}]', '["Roast diced potatoes at 425F for 25 minutes.", "Sear steak cubes in hot skillet 2-3 minutes per side.", "Add butter and garlic; toss to coat.", "Sprinkle with parsley.", "Serve over crispy potatoes."]', 40, 4, 23.00, 'Let steak rest 5 minutes before cutting to keep juices inside.', 'Inspired by Texas Roadhouse', TRUE),
  ('admin', NULL, 'Mediterranean Chickpea Bowls', 'healthy', 'Warm roasted chickpeas, fresh vegetables, and creamy yogurt sauce come together in a colorful bowl.', '[{"name": "canned chickpeas", "quantity": "2", "unit": "cans"}, {"name": "cucumber", "quantity": "1", "unit": ""}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "Greek yogurt", "quantity": "1", "unit": "cup"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "feta cheese", "quantity": "1/2", "unit": "cup"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}]', '["Roast chickpeas at 425F with olive oil, salt, pepper, and paprika for 20 minutes.", "Cook rice according to package.", "Dice cucumber and tomatoes.", "Mix yogurt with lemon juice and a pinch of salt.", "Assemble bowls with rice, vegetables, chickpeas, feta, and yogurt sauce."]', 35, 4, 11.00, 'Dry chickpeas thoroughly before roasting so they crisp instead of steaming.', 'Inspired by Sweetgreen', TRUE),
  ('admin', NULL, 'BBQ Pulled Pork Sliders', 'bbq', 'Tender pulled pork piled high on soft slider buns with tangy sauce tastes like weekend cookout comfort any night.', '[{"name": "pork shoulder chunks", "quantity": "2", "unit": "lbs"}, {"name": "barbecue sauce", "quantity": "1", "unit": "cup"}, {"name": "slider buns", "quantity": "10", "unit": ""}, {"name": "coleslaw mix", "quantity": "1", "unit": "bag"}, {"name": "mayo", "quantity": "1/4", "unit": "cup"}, {"name": "apple cider vinegar", "quantity": "1", "unit": "tbsp"}]', '["Season pork and sear in skillet.", "Add pork to pot with splash of water; cover and simmer 35-40 minutes until shreddable.", "Shred pork and stir in barbecue sauce.", "Toss coleslaw mix with mayo and vinegar.", "Build sliders and serve warm."]', 55, 5, 17.00, 'Toast slider buns lightly so they hold sauce without getting soggy.', 'Inspired by BJ''s Brewhouse', TRUE),
  ('admin', NULL, 'Garlic Shrimp Alfredo Pasta', 'seafood', 'Creamy parmesan Alfredo wraps around tender shrimp and pasta in a dinner that tastes restaurant-rich.', '[{"name": "shrimp peeled and deveined", "quantity": "1.5", "unit": "lbs"}, {"name": "fettuccine pasta", "quantity": "1", "unit": "lb"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "parmesan cheese", "quantity": "1", "unit": "cup"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}]', '["Boil pasta until al dente.", "Saute shrimp in butter and garlic for 2-3 minutes per side.", "Remove shrimp and add cream plus parmesan to skillet.", "Toss cooked pasta into sauce.", "Return shrimp and mix gently before serving."]', 30, 4, 21.00, 'Reserve pasta water to thin sauce if it thickens too much.', 'Inspired by Red Lobster', TRUE),
  ('admin', NULL, 'French Bistro Chicken and Potatoes', 'french', 'Crispy golden chicken thighs roast beside buttery potatoes and herbs for cozy European comfort.', '[{"name": "bone-in chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "baby potatoes", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garlic cloves", "quantity": "4", "unit": ""}, {"name": "fresh thyme", "quantity": "1", "unit": "tbsp"}, {"name": "chicken broth", "quantity": "1", "unit": "cup"}]', '["Heat oven to 425F.", "Toss potatoes with butter, garlic, salt, pepper, and thyme.", "Place chicken thighs skin-side up beside potatoes.", "Roast 35 minutes until crispy and fully cooked.", "Spoon pan juices over chicken before serving."]', 50, 4, 19.00, 'Pat chicken dry before roasting for crispier skin.', 'Inspired by French bistro tradition', TRUE),
  ('admin', NULL, 'Panda Orange Chicken Rice Bowls', 'asian', 'Crispy pan-seared chicken coated in sticky orange sauce tastes just like takeout without leaving home.', '[{"name": "chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "orange marmalade", "quantity": "1/2", "unit": "cup"}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "broccoli florets", "quantity": "1", "unit": "bag"}]', '["Cook rice.", "Dice chicken and cook in skillet until browned.", "Stir together orange marmalade and soy sauce.", "Add sauce to chicken and simmer until sticky.", "Steam broccoli and serve over rice."]', 30, 4, 15.00, 'Let the sauce bubble for 2-3 minutes so it clings to the chicken.', 'Inspired by Panda Express', TRUE),
  ('admin', NULL, 'Loaded Beef Taco Skillet', 'mexican', 'Savory taco beef layered with melty cheese, rice, and toppings turns taco night into a one-pan dinner.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "taco seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "cooked rice", "quantity": "2", "unit": "cups"}, {"name": "shredded cheddar cheese", "quantity": "2", "unit": "cups"}, {"name": "salsa", "quantity": "1", "unit": "cup"}, {"name": "shredded lettuce", "quantity": "1", "unit": "head"}, {"name": "sour cream", "quantity": "1", "unit": "cup"}]', '["Brown beef in large skillet and drain excess fat.", "Stir in taco seasoning and salsa.", "Add rice and simmer briefly.", "Sprinkle cheese over skillet and cover until melted.", "Serve topped with lettuce and sour cream."]', 30, 5, 16.00, 'Add crushed tortilla chips on top for crunch.', 'Inspired by On the Border', TRUE),
  ('admin', NULL, 'Creamy Sausage Tortellini Soup', 'italian', 'Cheese tortellini, sausage, and creamy broth come together in a rich soup that tastes restaurant cozy.', '[{"name": "Italian sausage", "quantity": "1.5", "unit": "lbs"}, {"name": "refrigerated cheese tortellini", "quantity": "1", "unit": "package"}, {"name": "chicken broth", "quantity": "6", "unit": "cups"}, {"name": "baby spinach", "quantity": "1", "unit": "bag"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}]', '["Brown sausage with onion and garlic.", "Add broth and bring to simmer.", "Stir in tortellini and cook according to package.", "Add cream and spinach.", "Simmer until spinach wilts."]', 35, 5, 18.75, 'Add tortellini at the end so it stays tender instead of mushy.', 'Inspired by Olive Garden', TRUE),
  ('admin', NULL, 'Steakhouse Mushroom Swiss Meatballs', 'steakhouse', 'Tender beef meatballs in savory mushroom gravy with melted Swiss cheese taste rich and indulgent.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "cremini mushrooms", "quantity": "8", "unit": "oz"}, {"name": "Swiss cheese shredded", "quantity": "1", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1", "unit": "cup"}, {"name": "egg", "quantity": "1", "unit": ""}, {"name": "beef broth", "quantity": "2", "unit": "cups"}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}]', '["Mix beef, breadcrumbs, egg, salt, and pepper; form meatballs.", "Bake meatballs at 400F for 18 minutes.", "Cook mushrooms in skillet.", "Add broth and simmer to create gravy.", "Stir in cheese and spoon over meatballs."]', 45, 4, 20.00, 'Bake meatballs on a rack for better browning all around.', 'Inspired by Ruth''s Chris', TRUE),
  ('admin', NULL, 'Indian Butter Chickpeas with Rice', 'indian', 'Creamy tomato-spiced chickpeas simmer into a rich comforting dinner that tastes deeply satisfying without being too spicy.', '[{"name": "canned chickpeas", "quantity": "2", "unit": "cans"}, {"name": "crushed tomatoes", "quantity": "1", "unit": "can"}, {"name": "heavy cream", "quantity": "1/2", "unit": "cup"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "curry powder", "quantity": "2", "unit": "tsp"}, {"name": "butter", "quantity": "2", "unit": "tbsp"}]', '["Cook rice according to package.", "Saute onion and garlic in butter.", "Stir in curry powder and tomatoes.", "Add chickpeas and simmer 15 minutes.", "Stir in cream and serve over rice."]', 35, 4, 11.00, 'Add a pinch of sugar if tomatoes taste too acidic.', 'Inspired by Indian dhaba tradition', TRUE),
  ('admin', NULL, 'Five Guys Patty Melt Skillet Sandwiches', 'american', 'Juicy beef patties, caramelized onions, and melted cheese pressed between buttery toasted bread create a diner-style dinner everyone loves.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "rye or sourdough bread", "quantity": "8", "unit": "slices"}, {"name": "yellow onions", "quantity": "2", "unit": ""}, {"name": "Swiss cheese slices", "quantity": "4", "unit": ""}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "Worcestershire sauce", "quantity": "1", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Cook onions in butter over low heat 15 minutes until caramelized.", "Mix ground beef with Worcestershire, garlic powder, salt, and pepper; form 4 patties.", "Cook patties in skillet 4-5 minutes per side.", "Place cheese on patties and let melt.", "Butter bread slices and toast in same skillet until golden.", "Assemble patty melts with caramelized onions and serve hot."]', 35, 4, 17.00, 'Use low heat for onions — caramelizing takes 15 minutes for real sweetness.', 'Inspired by Five Guys', TRUE),
  ('admin', NULL, 'Chicken Parmesan Pasta Bake', 'italian', 'Breaded chicken baked with marinara and mozzarella over pasta creates a crowd-pleasing family dinner.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "penne pasta", "quantity": "1", "unit": "lb"}, {"name": "marinara sauce", "quantity": "24", "unit": "oz"}, {"name": "shredded mozzarella", "quantity": "2", "unit": "cups"}, {"name": "parmesan cheese", "quantity": "1/2", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1", "unit": "cup"}, {"name": "eggs", "quantity": "2", "unit": ""}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Preheat oven to 400F. Cook pasta until just underdone; drain.", "Dip chicken in beaten egg then breadcrumbs; bake 20 minutes.", "Spread half the marinara in a 9x13 baking dish.", "Add pasta, remaining sauce, and sliced baked chicken.", "Top with mozzarella and parmesan.", "Bake 20 minutes until bubbly and golden."]', 50, 5, 19.00, 'Use day-old bread for breadcrumbs — they stay crispier in the oven.', 'Inspired by Maggiano''s', TRUE),
  ('admin', NULL, 'Beef Enchilada Rice Casserole', 'mexican', 'Layers of seasoned beef, rice, enchilada sauce, and melted cheese create all the flavors of enchiladas without the rolling.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "long grain rice", "quantity": "2", "unit": "cups"}, {"name": "red enchilada sauce", "quantity": "19", "unit": "oz can"}, {"name": "canned black beans", "quantity": "1", "unit": "can"}, {"name": "shredded Mexican cheese", "quantity": "2", "unit": "cups"}, {"name": "taco seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "chicken broth", "quantity": "2", "unit": "cups"}]', '["Brown beef with onion and taco seasoning; drain fat.", "Cook rice in broth according to package.", "Spread rice in a 9x13 baking dish.", "Top with beef, beans, and enchilada sauce.", "Sprinkle cheese over top.", "Bake at 375F for 20 minutes until cheese is bubbly."]', 45, 5, 17.00, 'Let casserole rest 5 minutes before scooping for cleaner servings.', 'Inspired by Chuy''s', TRUE),
  ('admin', NULL, 'Teriyaki Chicken and Broccoli', 'japanese', 'Sweet savory teriyaki glaze coats tender chicken and crisp broccoli over fluffy rice.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "soy sauce", "quantity": "1/4", "unit": "cup"}, {"name": "honey", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tsp"}, {"name": "cornstarch", "quantity": "1", "unit": "tbsp"}, {"name": "sesame seeds", "quantity": "1", "unit": "tbsp"}]', '["Cook rice according to package.", "Whisk soy sauce, honey, garlic, ginger, and cornstarch.", "Cook chicken in skillet over medium-high heat 6-7 minutes per side.", "Steam broccoli until tender-crisp, about 5 minutes.", "Pour sauce over chicken and simmer 2 minutes until thickened.", "Serve over rice, garnish with sesame seeds."]', 30, 4, 14.00, 'Let teriyaki sauce reduce until it coats the back of a spoon for restaurant thickness.', 'Inspired by Benihana', TRUE),
  ('admin', NULL, 'Greek Turkey Meatball Bowls', 'greek', 'Herb-seasoned turkey meatballs paired with rice, cucumber, tomatoes, and creamy tzatziki create a fresh yet filling dinner.', '[{"name": "ground turkey", "quantity": "1.5", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "cucumber", "quantity": "1", "unit": ""}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "Greek yogurt", "quantity": "1", "unit": "cup"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "2", "unit": "cloves"}, {"name": "dried oregano", "quantity": "2", "unit": "tsp"}, {"name": "feta cheese", "quantity": "1/2", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1/3", "unit": "cup"}]', '["Mix turkey with breadcrumbs, garlic, oregano, salt, and pepper; form meatballs.", "Bake meatballs at 400F for 18-20 minutes.", "Cook rice according to package.", "Mix yogurt with lemon juice and minced garlic for tzatziki.", "Dice cucumber and halve tomatoes.", "Assemble bowls with rice, meatballs, vegetables, tzatziki, and feta."]', 35, 4, 15.00, 'Wet your hands before rolling meatballs to prevent sticking.', 'Inspired by Greek taverna tradition', TRUE),
  ('admin', NULL, 'Nashville Hot Chicken Tenders', 'southern', 'Crispy oven-baked chicken tenders brushed with spicy Nashville-style butter deliver bold flavor without deep frying.', '[{"name": "chicken breast tenders", "quantity": "2", "unit": "lbs"}, {"name": "panko breadcrumbs", "quantity": "1.5", "unit": "cups"}, {"name": "eggs", "quantity": "2", "unit": ""}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "cayenne pepper", "quantity": "2", "unit": "tsp"}, {"name": "hot sauce", "quantity": "2", "unit": "tbsp"}, {"name": "brown sugar", "quantity": "1", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}]', '["Preheat oven to 425F. Cut potatoes into fries and bake 30 minutes.", "Dip tenders in beaten egg then panko; place on lined sheet pan.", "Bake tenders 20-22 minutes until golden and 165F.", "Melt butter with cayenne, hot sauce, brown sugar, and garlic powder.", "Brush hot butter generously over tenders immediately after baking.", "Serve with fries and ranch dressing."]', 40, 4, 16.00, 'Brush hot butter sauce on immediately after baking while chicken is still hot.', 'Inspired by Hattie B''s', TRUE),
  ('admin', NULL, 'Coconut Curry Chicken', 'thai', 'Tender chicken simmered in coconut curry sauce creates a rich dinner that feels restaurant quality.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "coconut milk", "quantity": "14", "unit": "oz can"}, {"name": "Thai red curry paste", "quantity": "2", "unit": "tbsp"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "fish sauce", "quantity": "1", "unit": "tbsp"}, {"name": "lime", "quantity": "1", "unit": ""}, {"name": "bell pepper", "quantity": "1", "unit": ""}]', '["Cook rice according to package.", "Cook garlic, ginger, and curry paste in oil 1 minute.", "Add coconut milk and bring to gentle simmer.", "Add chicken and bell pepper; simmer 18-20 minutes.", "Stir in fish sauce and lime juice.", "Serve over rice."]', 35, 4, 16.00, 'Add coconut milk last and don''t boil it — gentle simmer keeps the sauce silky.', 'Inspired by Thai street food tradition', TRUE),
  ('admin', NULL, 'Lemon Garlic Salmon Sheet Pan', 'healthy', 'Roasted salmon and vegetables cook together on one pan for a simple nutritious dinner.', '[{"name": "salmon fillets", "quantity": "2", "unit": "lbs"}, {"name": "asparagus", "quantity": "1", "unit": "lb"}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "dried Italian herbs", "quantity": "1", "unit": "tsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Preheat oven to 400F.", "Toss asparagus and tomatoes with oil, garlic, salt, and pepper; roast 10 minutes.", "Place salmon on pan; drizzle with oil, herbs, and lemon slices.", "Roast everything together 12-15 more minutes until salmon flakes.", "Squeeze fresh lemon over pan and serve."]', 30, 4, 23.00, 'Start vegetables 10 minutes before salmon — they need more time in the oven.', 'Inspired by Sweetgreen', TRUE),
  ('admin', NULL, 'Capital Grille Beef Stroganoff', 'steakhouse', 'Tender beef and mushrooms tossed in creamy sauce over noodles create an upscale comfort-food classic.', '[{"name": "sirloin steak strips", "quantity": "2", "unit": "lbs"}, {"name": "egg noodles", "quantity": "12", "unit": "oz"}, {"name": "cremini mushrooms", "quantity": "8", "unit": "oz"}, {"name": "beef broth", "quantity": "1.5", "unit": "cups"}, {"name": "sour cream", "quantity": "1", "unit": "cup"}, {"name": "Worcestershire sauce", "quantity": "2", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "flour", "quantity": "2", "unit": "tbsp"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}]', '["Cook egg noodles; drain and set aside.", "Sear steak strips in butter over high heat 2 minutes; remove.", "Cook mushrooms and onion in same pan until golden.", "Whisk in flour, then broth and Worcestershire; simmer until thickened.", "Remove from heat and stir in sour cream.", "Toss noodles with sauce and steak; serve immediately."]', 45, 4, 22.00, 'Stir sour cream in off the heat to prevent it from breaking in the sauce.', 'Inspired by Capital Grille', TRUE),
  ('admin', NULL, 'Garlic Butter Crab Pasta', 'seafood', 'Sweet crab meat tossed with garlic butter and pasta tastes elegant while remaining approachable.', '[{"name": "lump crab meat", "quantity": "1", "unit": "lb"}, {"name": "linguine pasta", "quantity": "1", "unit": "lb"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "dry white wine or chicken broth", "quantity": "1/2", "unit": "cup"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "fresh parsley", "quantity": "1/4", "unit": "cup"}, {"name": "red pepper flakes", "quantity": "1/2", "unit": "tsp"}]', '["Cook linguine until al dente; reserve 1/2 cup pasta water.", "Melt butter over medium heat and saute garlic 1 minute.", "Add wine and reduce by half, about 2 minutes.", "Add crab and toss gently to warm through.", "Toss pasta with crab sauce, adding pasta water to loosen.", "Finish with lemon juice and parsley."]', 30, 4, 21.00, 'Toss pasta with crab off heat so the crab stays tender and doesn''t overcook.', 'Inspired by Joe''s Crab Shack', TRUE),
  ('admin', NULL, 'French Onion Chicken Skillet', 'french', 'Golden onions melt into a savory sauce beneath juicy chicken and bubbling cheese.', '[{"name": "bone-in chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "yellow onions", "quantity": "3", "unit": ""}, {"name": "beef broth", "quantity": "1.5", "unit": "cups"}, {"name": "Swiss or Gruyere cheese", "quantity": "1.5", "unit": "cups"}, {"name": "fresh thyme", "quantity": "1", "unit": "tbsp"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "flour", "quantity": "1", "unit": "tbsp"}, {"name": "garlic", "quantity": "2", "unit": "cloves"}]', '["Cook onions in butter over low heat 15-18 minutes until caramelized.", "Season chicken and sear skin-side down 5 minutes; flip and cook 5 more.", "Remove chicken; whisk flour into onions, then add broth and thyme.", "Return chicken to skillet; cover and simmer 15 minutes.", "Top chicken with cheese and broil 2-3 minutes until bubbly.", "Serve with crusty bread to scoop up the sauce."]', 50, 4, 19.00, 'Don''t rush caramelizing the onions — 15 minutes of patience is the secret.', 'Inspired by French bistro tradition', TRUE),
  ('admin', NULL, 'BBQ Bacon Meatloaf', 'american', 'Classic meatloaf glazed with smoky barbecue sauce becomes even better with crispy bacon on top.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "bacon strips", "quantity": "6", "unit": ""}, {"name": "panko breadcrumbs", "quantity": "1", "unit": "cup"}, {"name": "eggs", "quantity": "2", "unit": ""}, {"name": "milk", "quantity": "1/4", "unit": "cup"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "BBQ sauce", "quantity": "1/2", "unit": "cup"}, {"name": "Worcestershire sauce", "quantity": "2", "unit": "tbsp"}, {"name": "ketchup", "quantity": "1/4", "unit": "cup"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Preheat oven to 375F. Dice onion finely.", "Mix beef, breadcrumbs, eggs, milk, onion, Worcestershire, ketchup, garlic powder, salt, and pepper.", "Form into loaf in a baking dish.", "Spread BBQ sauce over top; drape bacon strips across.", "Bake 50-55 minutes until internal temp reaches 160F.", "Rest 10 minutes before slicing."]', 60, 6, 19.50, 'Let meatloaf rest 10 minutes before slicing — it holds together much better.', 'Inspired by Bob Evans', TRUE),
  ('admin', NULL, 'Creamy Chicken Florentine Pasta', 'italian', 'Tender chicken, spinach, and creamy parmesan sauce coat pasta in every bite.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "penne pasta", "quantity": "1", "unit": "lb"}, {"name": "baby spinach", "quantity": "3", "unit": "cups"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "parmesan cheese", "quantity": "1", "unit": "cup"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "sun-dried tomatoes", "quantity": "1/3", "unit": "cup"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}]', '["Cook pasta until al dente; reserve 1/2 cup pasta water.", "Season and cook chicken in oil 6 minutes per side; slice.", "Saute garlic and sun-dried tomatoes in same pan.", "Add cream and parmesan; simmer until slightly thickened.", "Add spinach and stir until wilted.", "Toss pasta with sauce and chicken; add pasta water to loosen."]', 40, 5, 18.00, 'Wilt spinach directly into the hot cream sauce — it takes only 60 seconds.', 'Inspired by Carrabba''s', TRUE),
  ('admin', NULL, 'Pork Carnitas Rice Bowls', 'latin', 'Slow-simmered pork with lime rice and fresh toppings creates a customizable dinner everyone can build themselves.', '[{"name": "pork shoulder chunks", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "canned black beans", "quantity": "1", "unit": "can"}, {"name": "lime", "quantity": "3", "unit": ""}, {"name": "orange juice", "quantity": "1/2", "unit": "cup"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "cumin", "quantity": "2", "unit": "tsp"}, {"name": "chili powder", "quantity": "1", "unit": "tsp"}, {"name": "cilantro", "quantity": "1/4", "unit": "cup"}, {"name": "sour cream", "quantity": "1", "unit": "cup"}]', '["Season pork with cumin, chili powder, salt, and pepper.", "Add pork to pan with orange juice, garlic, and splash of water; simmer covered 40 minutes.", "Shred pork and spread on sheet pan; broil 5 minutes for crispy edges.", "Cook rice and fluff with lime juice and cilantro.", "Warm black beans.", "Assemble bowls with carnitas, rice, beans, and toppings."]', 55, 5, 19.00, 'Broil shredded carnitas for 5 minutes for crispy edges like authentic Mexican taquerias.', 'Inspired by Chipotle', TRUE),
  ('admin', NULL, 'Sesame Ginger Beef Noodles', 'asian', 'Savory beef, noodles, and vegetables tossed in sesame ginger sauce create a quick restaurant-style dinner.', '[{"name": "ground beef or flank steak strips", "quantity": "1.5", "unit": "lbs"}, {"name": "spaghetti noodles", "quantity": "1", "unit": "lb"}, {"name": "soy sauce", "quantity": "1/4", "unit": "cup"}, {"name": "sesame oil", "quantity": "2", "unit": "tbsp"}, {"name": "fresh ginger grated", "quantity": "1", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "shredded carrots", "quantity": "2", "unit": ""}, {"name": "honey", "quantity": "2", "unit": "tbsp"}, {"name": "rice vinegar", "quantity": "1", "unit": "tbsp"}]', '["Cook noodles until just al dente; drain.", "Whisk soy sauce, sesame oil, ginger, honey, and vinegar.", "Cook beef over high heat until browned; add garlic.", "Add carrots and cook 2 minutes.", "Toss noodles with beef and sauce over medium heat.", "Finish with green onions and serve."]', 30, 4, 18.00, 'Cook noodles slightly underdone — they finish cooking when tossed in the hot sauce.', 'Inspired by PF Chang''s', TRUE),
  ('admin', NULL, 'Mediterranean Shrimp Couscous Bowls', 'mediterranean', 'Tender shrimp, fluffy couscous, and bright vegetables combine for a fresh flavorful dinner.', '[{"name": "large shrimp peeled", "quantity": "1.5", "unit": "lbs"}, {"name": "couscous", "quantity": "2", "unit": "cups"}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "cucumber", "quantity": "1", "unit": ""}, {"name": "kalamata olives", "quantity": "1/2", "unit": "cup"}, {"name": "feta cheese", "quantity": "1/2", "unit": "cup"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "fresh parsley", "quantity": "1/4", "unit": "cup"}]', '["Pour boiling water over couscous; cover and let stand 5 minutes; fluff with fork.", "Saute shrimp with garlic and olive oil 2-3 minutes per side.", "Halve tomatoes and dice cucumber.", "Drizzle couscous with olive oil and lemon juice.", "Assemble bowls with couscous, vegetables, shrimp, olives, and feta.", "Finish with fresh parsley."]', 30, 4, 19.00, 'Fluff couscous with a fork and a drizzle of olive oil for light non-clumpy texture.', 'Inspired by Mediterranean tradition', TRUE),
  ('admin', NULL, 'Smoked Sausage and Mac & Cheese', 'southern', 'Creamy homemade macaroni paired with smoky sausage creates a hearty family meal.', '[{"name": "smoked sausage or kielbasa", "quantity": "14", "unit": "oz"}, {"name": "elbow pasta", "quantity": "1", "unit": "lb"}, {"name": "shredded sharp cheddar", "quantity": "3", "unit": "cups"}, {"name": "milk", "quantity": "2", "unit": "cups"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "flour", "quantity": "3", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "yellow mustard", "quantity": "1", "unit": "tsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Cook pasta until al dente; drain.", "Slice sausage and brown in skillet until caramelized; remove.", "Melt butter in same pan; whisk in flour and cook 1 minute.", "Add milk gradually, stirring until smooth and thickened.", "Stir in cheese, mustard, salt, and pepper.", "Fold in pasta and sausage; serve hot."]', 40, 5, 17.00, 'Brown sausage slices until caramelized — the char adds deep flavor to the mild mac.', 'Inspired by Cracker Barrel', TRUE),
  ('admin', NULL, 'Butter Chicken Rice Bowls', 'indian', 'Creamy tomato butter sauce wraps around tender chicken for a comforting dinner with mild warming spices.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "crushed tomatoes", "quantity": "14", "unit": "oz can"}, {"name": "heavy cream", "quantity": "1/2", "unit": "cup"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garam masala", "quantity": "2", "unit": "tsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "cumin", "quantity": "1", "unit": "tsp"}]', '["Cook rice according to package.", "Cook diced onion in butter until soft, about 5 minutes.", "Add garlic, ginger, cumin, and garam masala; stir 1 minute.", "Add crushed tomatoes; simmer 10 minutes.", "Add chicken pieces and simmer 15 minutes until cooked through.", "Stir in cream and serve over rice."]', 40, 4, 17.00, 'Bloom spices in butter for 60 seconds before adding liquid to deepen flavor.', 'Inspired by Indian dhaba tradition', TRUE),
  ('admin', NULL, 'Turkey Taco Lettuce Bowls', 'healthy', 'Lean turkey, fresh vegetables, and avocado create a lighter take on taco night.', '[{"name": "ground turkey", "quantity": "1.5", "unit": "lbs"}, {"name": "romaine lettuce heads", "quantity": "2", "unit": ""}, {"name": "avocado", "quantity": "2", "unit": ""}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "canned black beans", "quantity": "1", "unit": "can"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "taco seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "sour cream", "quantity": "1/2", "unit": "cup"}, {"name": "shredded cheddar", "quantity": "1", "unit": "cup"}]', '["Brown turkey in skillet with taco seasoning and 1/4 cup water.", "Warm black beans; drain.", "Slice avocado and halve tomatoes.", "Separate lettuce leaves to use as cups.", "Fill lettuce cups with turkey, beans, tomatoes, and avocado.", "Top with sour cream, cheese, and squeeze of lime."]', 30, 4, 13.00, 'Season turkey generously — lean meat needs bold spices to shine.', 'Inspired by healthy restaurant tradition', TRUE),
  ('admin', NULL, 'Outback Peppercorn Sirloin', 'steakhouse', 'Pepper-crusted sirloin paired with garlic mashed potatoes feels like a steakhouse date night at home.', '[{"name": "sirloin steaks", "quantity": "4", "unit": "steaks"}, {"name": "cracked black peppercorns", "quantity": "3", "unit": "tbsp"}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "heavy cream", "quantity": "1/2", "unit": "cup"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "salt", "quantity": "", "unit": "to taste"}]', '["Boil potatoes until fork-tender; drain.", "Press cracked peppercorns firmly into both sides of each steak.", "Sear steaks in cast iron with oil over high heat 4-5 minutes per side.", "Rest steaks 5 minutes.", "Mash potatoes with butter, cream, and roasted garlic.", "Serve steaks over mashed potatoes."]', 35, 4, 24.00, 'Press cracked peppercorns firmly into steak by hand so they stay on during searing.', 'Inspired by Outback Steakhouse', TRUE),
  ('admin', NULL, 'Cajun Shrimp and Rice Skillet', 'seafood', 'Bold Cajun spices and juicy shrimp transform simple rice into a flavorful one-pan meal.', '[{"name": "large shrimp peeled", "quantity": "1.5", "unit": "lbs"}, {"name": "long grain rice", "quantity": "2", "unit": "cups"}, {"name": "Cajun seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "chicken broth", "quantity": "4", "unit": "cups"}, {"name": "bell peppers", "quantity": "2", "unit": ""}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "celery", "quantity": "3", "unit": "stalks"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}]', '["Saute onion, celery, and peppers in oil until softened.", "Add garlic and 1 tbsp Cajun seasoning; stir 1 minute.", "Add rice and broth; bring to boil then reduce and cover 18 minutes.", "Season shrimp with remaining Cajun spice.", "Add shrimp to skillet on top of rice; cover 5 minutes until cooked.", "Fluff rice and serve."]', 30, 4, 19.00, 'Add shrimp last so they don''t overcook while the rice finishes.', 'Inspired by Pappadeaux', TRUE),
  ('admin', NULL, 'Chicken Cordon Bleu Casserole', 'french', 'Ham, chicken, and creamy Swiss cheese sauce bake together into an easy family casserole.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "deli ham slices", "quantity": "6", "unit": "oz"}, {"name": "Swiss cheese shredded", "quantity": "2", "unit": "cups"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "Dijon mustard", "quantity": "2", "unit": "tbsp"}, {"name": "panko breadcrumbs", "quantity": "1", "unit": "cup"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Preheat oven to 375F.", "Slice chicken breasts in half horizontally; layer in baking dish.", "Lay ham slices over chicken.", "Whisk cream, Dijon, and garlic powder; pour over chicken and ham.", "Top with Swiss cheese.", "Mix breadcrumbs with melted butter; sprinkle over top. Bake 35-40 minutes."]', 50, 5, 19.00, 'Pound chicken to even thickness so it cooks at the same rate as the ham layer.', 'Inspired by French tradition', TRUE),
  ('admin', NULL, 'Whataburger Patty Melt Pasta', 'american', 'Ground beef, onions, cheese, and pasta combine into a fun twist on the famous patty melt.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "penne or rotini pasta", "quantity": "1", "unit": "lb"}, {"name": "yellow onion", "quantity": "1", "unit": ""}, {"name": "shredded cheddar cheese", "quantity": "2", "unit": "cups"}, {"name": "beef broth", "quantity": "2", "unit": "cups"}, {"name": "Worcestershire sauce", "quantity": "2", "unit": "tbsp"}, {"name": "Thousand Island dressing", "quantity": "1/3", "unit": "cup"}, {"name": "tomato paste", "quantity": "2", "unit": "tbsp"}]', '["Cook pasta until al dente; drain.", "Brown beef with diced onion; drain fat.", "Add tomato paste, Worcestershire, and broth; simmer 5 minutes.", "Toss pasta into beef mixture.", "Sprinkle cheese over top and stir until melted.", "Drizzle Thousand Island over each serving."]', 30, 5, 16.00, 'Use Thousand Island dressing as the finishing sauce — it''s the secret to burger pasta flavor.', 'Inspired by Whataburger', TRUE),
  ('admin', NULL, 'Baked Ziti Supreme', 'italian', 'Layers of pasta, marinara, beef, and bubbling mozzarella create the ultimate family-style dinner.', '[{"name": "ziti pasta", "quantity": "1", "unit": "lb"}, {"name": "ground beef or Italian sausage", "quantity": "1.5", "unit": "lbs"}, {"name": "marinara sauce", "quantity": "48", "unit": "oz"}, {"name": "ricotta cheese", "quantity": "15", "unit": "oz"}, {"name": "shredded mozzarella", "quantity": "3", "unit": "cups"}, {"name": "parmesan cheese", "quantity": "1/2", "unit": "cup"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "Italian seasoning", "quantity": "2", "unit": "tsp"}]', '["Cook pasta until just underdone; drain.", "Brown meat with garlic and Italian seasoning; stir in marinara.", "Spread 1 cup sauce in 9x13 dish.", "Mix pasta with half the sauce and ricotta; layer in dish.", "Top with remaining meat sauce, mozzarella, and parmesan.", "Cover and bake at 375F for 25 minutes; uncover and bake 15 more."]', 50, 6, 21.00, 'Cover with foil for the first 20 minutes then uncover to bubble and brown the cheese.', 'Inspired by Buca di Beppo', TRUE),
  ('admin', NULL, 'Steak Fajita Sheet Pan Dinner', 'mexican', 'Tender steak, peppers, and onions roast together on one pan for easy fajita night.', '[{"name": "flank steak", "quantity": "2", "unit": "lbs"}, {"name": "bell peppers mixed", "quantity": "3", "unit": ""}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "flour tortillas", "quantity": "8", "unit": ""}, {"name": "fajita seasoning", "quantity": "3", "unit": "tbsp"}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "sour cream", "quantity": "1", "unit": "cup"}, {"name": "guacamole", "quantity": "1", "unit": "cup"}]', '["Preheat oven to 425F.", "Slice steak, peppers, and onion into strips.", "Toss with oil, fajita seasoning, and lime juice; spread on sheet pan.", "Roast 18-20 minutes until steak is cooked and peppers slightly charred.", "Rest steak 5 minutes; slice against the grain.", "Serve with warm tortillas, sour cream, and guacamole."]', 35, 4, 21.00, 'Slice steak against the grain after resting for the most tender pieces.', 'Inspired by Chili''s', TRUE),
  ('admin', NULL, 'Mongolian Beef Rice Bowls', 'asian', 'Tender beef coated in a sweet soy glaze served over fluffy rice.', '[{"name": "flank steak thinly sliced", "quantity": "1.5", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "soy sauce", "quantity": "1/4", "unit": "cup"}, {"name": "brown sugar", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "cornstarch", "quantity": "3", "unit": "tbsp"}, {"name": "vegetable oil", "quantity": "3", "unit": "tbsp"}, {"name": "red pepper flakes", "quantity": "1/2", "unit": "tsp"}]', '["Cook rice according to package.", "Toss beef slices in cornstarch until coated.", "Fry beef in hot oil in batches 2-3 minutes until crispy; remove.", "Saute garlic and ginger; add soy sauce, sugar, and red pepper flakes.", "Return beef to pan and toss in sauce 1-2 minutes.", "Serve over rice, garnish with green onions."]', 25, 4, 19.00, 'Coat beef in cornstarch before frying for the crispy crust Mongolian beef is known for.', 'Inspired by PF Chang''s', TRUE),
  ('admin', NULL, 'Greek Lemon Shrimp Orzo', 'greek', 'Bright lemon shrimp tossed with tender orzo and feta creates a light but satisfying family dinner.', '[{"name": "large shrimp peeled", "quantity": "1.5", "unit": "lbs"}, {"name": "orzo pasta", "quantity": "1.5", "unit": "cups"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "feta cheese", "quantity": "3/4", "unit": "cup"}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "fresh dill or parsley", "quantity": "1/4", "unit": "cup"}, {"name": "baby spinach", "quantity": "2", "unit": "cups"}]', '["Cook orzo according to package; drain.", "Saute garlic in oil over medium-high heat 30 seconds.", "Add shrimp; cook 2 minutes per side until pink.", "Add spinach and stir until wilted.", "Toss orzo with shrimp, lemon juice, lemon zest, and tomatoes.", "Top with feta and fresh herbs."]', 35, 4, 19.00, 'Add lemon zest along with juice for extra bright citrus flavor.', 'Inspired by Greek taverna tradition', TRUE),
  ('admin', NULL, 'BBQ Chicken Loaded Potato Bowls', 'bbq', 'Crispy roasted potatoes topped with barbecue chicken and melted cheese. Comfort food meets game-day flavor.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}, {"name": "BBQ sauce", "quantity": "3/4", "unit": "cup"}, {"name": "shredded cheddar cheese", "quantity": "1.5", "unit": "cups"}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "sour cream", "quantity": "1/2", "unit": "cup"}, {"name": "bacon strips", "quantity": "4", "unit": ""}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Preheat oven to 425F. Cube potatoes and toss with oil, garlic powder, salt, and pepper.", "Roast potatoes 30 minutes without stirring.", "Cook chicken in skillet 6-7 minutes per side; toss with BBQ sauce.", "Cook bacon until crispy; crumble.", "Slice BBQ chicken.", "Assemble bowls with potatoes, chicken, cheese, sour cream, bacon, and green onions."]', 45, 4, 15.00, 'Roast potatoes at high heat without stirring for the first 20 minutes for crispier edges.', 'Inspired by Yard House', TRUE),
  ('admin', NULL, 'Thai Basil Ground Pork Rice', 'thai', 'Savory ground pork with garlic and sweet soy flavors makes a simple but deeply satisfying dinner.', '[{"name": "ground pork", "quantity": "1.5", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "fresh basil", "quantity": "1", "unit": "cup"}, {"name": "oyster sauce", "quantity": "3", "unit": "tbsp"}, {"name": "soy sauce", "quantity": "2", "unit": "tbsp"}, {"name": "fish sauce", "quantity": "1", "unit": "tbsp"}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "red pepper flakes", "quantity": "1", "unit": "tsp"}, {"name": "eggs", "quantity": "4", "unit": ""}, {"name": "vegetable oil", "quantity": "2", "unit": "tbsp"}]', '["Cook rice according to package.", "Fry one egg per person in oil; set aside.", "Saute garlic with oil over high heat 30 seconds.", "Add pork and cook breaking up until no longer pink.", "Add oyster sauce, soy sauce, fish sauce, and pepper flakes; stir 1 minute.", "Fold in basil leaves off heat. Serve over rice topped with fried egg."]', 25, 4, 14.00, 'High heat is essential — stir fry quickly so pork caramelizes instead of steaming.', 'Inspired by Thai street food tradition', TRUE),
  ('admin', NULL, 'Chicken and Vegetable Grain Bowls', 'healthy', 'Roasted chicken and colorful vegetables served over grains create a balanced dinner packed with flavor.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "quinoa or brown rice", "quantity": "2", "unit": "cups"}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "sweet potato", "quantity": "2", "unit": ""}, {"name": "olive oil", "quantity": "4", "unit": "tbsp"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "paprika", "quantity": "1", "unit": "tsp"}, {"name": "baby spinach", "quantity": "3", "unit": "cups"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Preheat oven to 425F.", "Cook quinoa or rice according to package.", "Cube sweet potatoes and cut broccoli; toss with oil, garlic, paprika, salt, and pepper.", "Place chicken and vegetables on sheet pan; roast 25-28 minutes.", "Slice chicken.", "Assemble bowls with grains, spinach, roasted vegetables, and chicken; drizzle with lemon."]', 35, 4, 15.00, 'Roast everything on one pan — chicken and vegetables at 425F together saves time.', 'Inspired by Sweetgreen', TRUE),
  ('admin', NULL, 'Mastro''s Garlic Herb Ribeye Bites', 'steakhouse', 'Juicy steak bites seared in garlic herb butter deliver steakhouse flavor in a quick family-friendly format.', '[{"name": "ribeye steak cubed", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "fresh rosemary", "quantity": "2", "unit": "sprigs"}, {"name": "fresh thyme", "quantity": "3", "unit": "sprigs"}, {"name": "coarse salt", "quantity": "1", "unit": "tsp"}, {"name": "cracked black pepper", "quantity": "1", "unit": "tsp"}, {"name": "baby potatoes", "quantity": "1.5", "unit": "lbs"}]', '["Boil baby potatoes until just tender; drain and halve.", "Season steak cubes with coarse salt and black pepper.", "Heat cast iron skillet until smoking.", "Sear steak in batches 2 minutes per side; do not crowd pan.", "Add butter, garlic, rosemary, and thyme; baste steak 1-2 minutes.", "Serve steak bites over potatoes with herb butter spooned over top."]', 30, 4, 25.00, 'Sear in batches — overcrowding the pan steams the steak instead of searing it.', 'Inspired by Mastro''s', TRUE),
  ('admin', NULL, 'New England Seafood Chowder', 'seafood', 'Creamy chowder loaded with fish, shrimp, and potatoes creates a cozy restaurant-style dinner.', '[{"name": "cod or halibut fillets", "quantity": "1", "unit": "lb"}, {"name": "large shrimp", "quantity": "1", "unit": "lb"}, {"name": "Yukon gold potatoes", "quantity": "1.5", "unit": "lbs"}, {"name": "heavy cream", "quantity": "1.5", "unit": "cups"}, {"name": "chicken broth", "quantity": "3", "unit": "cups"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "celery", "quantity": "3", "unit": "stalks"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "fresh thyme", "quantity": "1", "unit": "tsp"}, {"name": "bacon", "quantity": "4", "unit": "strips"}]', '["Cook bacon until crispy; reserve drippings. Crumble and set aside.", "Saute onion and celery in butter and bacon drippings until soft.", "Add broth and potatoes; simmer 15 minutes until potatoes are tender.", "Add fish chunks and shrimp; cook 8 minutes.", "Stir in cream and thyme; heat gently \u2014 do not boil.", "Serve topped with crumbled bacon."]', 45, 5, 24.00, 'Add seafood in the last 8 minutes so it stays tender and doesn''t toughen.', 'Inspired by Legal Sea Foods', TRUE),
  ('admin', NULL, 'Chicken Dijon Skillet', 'french', 'Tender chicken simmered in a creamy Dijon sauce feels elegant but approachable.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "Dijon mustard", "quantity": "3", "unit": "tbsp"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "shallots", "quantity": "3", "unit": ""}, {"name": "dry white wine or chicken broth", "quantity": "1/2", "unit": "cup"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "fresh thyme", "quantity": "1", "unit": "tbsp"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}]', '["Season chicken and sear in butter 5-6 minutes per side until golden; remove.", "Saute shallots and garlic in same pan until soft.", "Add wine and reduce by half.", "Whisk in cream and Dijon; simmer 3 minutes until slightly thickened.", "Return chicken to pan with thyme; simmer covered 10 minutes.", "Serve with crusty bread or mashed potatoes."]', 40, 4, 17.00, 'Use a generous amount of Dijon — it mellows in the cream and becomes the flavor backbone.', 'Inspired by French bistro tradition', TRUE),
  ('admin', NULL, 'Double Bacon Cheeseburger Casserole', 'american', 'Ground beef, bacon, cheese, and pasta combine into an irresistible comfort-food casserole.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "bacon strips", "quantity": "6", "unit": ""}, {"name": "penne pasta", "quantity": "1", "unit": "lb"}, {"name": "shredded cheddar cheese", "quantity": "3", "unit": "cups"}, {"name": "beef broth", "quantity": "2", "unit": "cups"}, {"name": "tomato paste", "quantity": "2", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "Worcestershire sauce", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "milk", "quantity": "1", "unit": "cup"}]', '["Cook pasta until al dente; drain.", "Cook bacon until crispy; crumble. Reserve 1 tbsp drippings.", "Brown beef with onion and garlic; drain fat.", "Add tomato paste, Worcestershire, broth, and milk; simmer 5 minutes.", "Toss pasta with beef mixture and bacon in baking dish.", "Top with cheddar and bake at 375F for 20 minutes until bubbly."]', 45, 6, 21.00, 'Top with extra cheese in the last 5 minutes uncovered for a golden cheesy crust.', 'Inspired by Shake Shack', TRUE),
  ('admin', NULL, 'Chicken Marsala Pasta', 'italian', 'Tender chicken and mushrooms tossed in a savory Marsala-style sauce over pasta.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "cremini mushrooms", "quantity": "8", "unit": "oz"}, {"name": "penne or fettuccine pasta", "quantity": "1", "unit": "lb"}, {"name": "Marsala wine or chicken broth", "quantity": "3/4", "unit": "cup"}, {"name": "heavy cream", "quantity": "3/4", "unit": "cup"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh parsley", "quantity": "1/4", "unit": "cup"}]', '["Cook pasta until al dente; drain and reserve 1/2 cup pasta water.", "Pound chicken to even thickness; season and sear in butter 4-5 minutes per side; remove.", "Cook mushrooms until golden; add garlic.", "Pour in Marsala and reduce by half.", "Add cream and simmer 3 minutes; return chicken.", "Toss pasta into sauce with pasta water as needed; garnish with parsley."]', 40, 4, 18.00, 'Use Marsala wine if available — even cheap cooking Marsala transforms this sauce.', 'Inspired by Olive Garden', TRUE),
  ('admin', NULL, 'Beef and Bean Burrito Skillet', 'mexican', 'Seasoned beef, beans, rice, and cheese in one pan. All the flavors of a burrito with easy cleanup.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "pinto or black beans", "quantity": "1", "unit": "can"}, {"name": "long grain rice", "quantity": "1.5", "unit": "cups"}, {"name": "red enchilada sauce or salsa", "quantity": "1", "unit": "cup"}, {"name": "shredded cheddar cheese", "quantity": "2", "unit": "cups"}, {"name": "taco seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "chicken broth", "quantity": "2.5", "unit": "cups"}]', '["Brown beef with onion and garlic; drain fat.", "Stir in taco seasoning and enchilada sauce.", "Add rice and broth; bring to boil then simmer covered 18 minutes.", "Drain and add beans; stir into rice mixture.", "Sprinkle cheese over top; cover until melted.", "Serve directly from skillet."]', 30, 5, 16.00, 'Stir in salsa with the beef for layered flavor in every bite.', 'Inspired by On the Border', TRUE),
  ('admin', NULL, 'Japanese Teriyaki Salmon Bowls', 'japanese', 'Sweet teriyaki glaze transforms roasted salmon into a restaurant-worthy dinner.', '[{"name": "salmon fillets", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "honey", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "2", "unit": "cloves"}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "sesame seeds", "quantity": "1", "unit": "tbsp"}, {"name": "green onions", "quantity": "3", "unit": ""}, {"name": "cornstarch", "quantity": "1", "unit": "tsp"}]', '["Cook rice according to package.", "Whisk soy sauce, honey, garlic, and cornstarch.", "Place salmon on lined sheet pan; brush with half the teriyaki sauce.", "Roast at 400F for 12 minutes.", "Brush with remaining sauce; roast 3-5 more minutes until glazed.", "Steam broccoli; assemble bowls with rice, salmon, and broccoli; garnish with sesame seeds and green onions."]', 30, 4, 23.00, 'Brush salmon with teriyaki sauce twice during baking for a thick glossy glaze.', 'Inspired by Japanese izakaya tradition', TRUE),
  ('admin', NULL, 'Greek Chicken and Rice Bake', 'mediterranean', 'Lemon chicken baked over rice with herbs creates a comforting one-pan dinner.', '[{"name": "bone-in chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "long grain rice", "quantity": "2", "unit": "cups"}, {"name": "chicken broth", "quantity": "3", "unit": "cups"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "dried oregano", "quantity": "2", "unit": "tsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Preheat oven to 400F.", "Saute onion and garlic in oil until soft; add rice and stir 1 minute.", "Transfer to 9x13 baking dish; pour broth and lemon juice over rice.", "Season chicken with oregano, salt, pepper, and remaining lemon zest; place skin-side up over rice.", "Cover and bake 30 minutes; uncover and bake 15 more until chicken is golden.", "Squeeze fresh lemon over dish before serving."]', 50, 5, 18.00, 'Uncover the last 10 minutes to crisp the chicken skin and absorb remaining liquid.', 'Inspired by Mediterranean tradition', TRUE),
  ('admin', NULL, 'Smoked Sausage BBQ Mac Bowls', 'southern', 'Smoky sausage, creamy macaroni, and barbecue sauce combine into a hearty comfort-food dinner.', '[{"name": "smoked sausage sliced", "quantity": "14", "unit": "oz"}, {"name": "elbow pasta", "quantity": "1", "unit": "lb"}, {"name": "shredded cheddar cheese", "quantity": "3", "unit": "cups"}, {"name": "milk", "quantity": "2", "unit": "cups"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "flour", "quantity": "3", "unit": "tbsp"}, {"name": "BBQ sauce", "quantity": "1/4", "unit": "cup"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Cook pasta until al dente; drain.", "Brown sausage slices in skillet until caramelized; remove.", "Melt butter; saute diced onion 3 minutes. Whisk in flour.", "Add milk gradually, stirring until smooth and thickened.", "Stir in cheese and garlic powder until melted.", "Fold in pasta and sausage; serve in bowls with BBQ sauce drizzled over top."]', 35, 5, 17.00, 'Drizzle BBQ sauce over the finished bowl instead of mixing it in for better control.', 'Inspired by Lazy Dog', TRUE),
  ('admin', NULL, 'Coconut Chickpea Curry', 'indian', 'Creamy coconut curry loaded with chickpeas creates a filling vegetarian dinner packed with flavor.', '[{"name": "canned chickpeas", "quantity": "2", "unit": "cans"}, {"name": "coconut milk", "quantity": "14", "unit": "oz can"}, {"name": "diced tomatoes", "quantity": "14", "unit": "oz can"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "curry powder", "quantity": "2", "unit": "tsp"}, {"name": "garam masala", "quantity": "1", "unit": "tsp"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "coconut oil or butter", "quantity": "2", "unit": "tbsp"}, {"name": "fresh cilantro", "quantity": "1/4", "unit": "cup"}]', '["Cook rice according to package.", "Saute onion in oil until soft, about 5 minutes.", "Add garlic, ginger, curry powder, and garam masala; stir 1 minute.", "Add diced tomatoes; simmer 5 minutes.", "Stir in coconut milk and chickpeas; simmer uncovered 10 minutes.", "Serve over rice topped with fresh cilantro."]', 35, 4, 11.00, 'Let curry simmer uncovered the last 5 minutes to concentrate the flavors.', 'Inspired by Indian dhaba tradition', TRUE),
  ('admin', NULL, 'Turkey Mediterranean Lettuce Wraps', 'healthy', 'Lean turkey, vegetables, and feta wrapped in crisp lettuce for a light dinner with plenty of flavor.', '[{"name": "ground turkey", "quantity": "1.5", "unit": "lbs"}, {"name": "romaine or butter lettuce", "quantity": "2", "unit": "heads"}, {"name": "feta cheese", "quantity": "3/4", "unit": "cup"}, {"name": "cucumber diced", "quantity": "1", "unit": ""}, {"name": "cherry tomatoes halved", "quantity": "1", "unit": "pint"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "dried oregano", "quantity": "2", "unit": "tsp"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "kalamata olives sliced", "quantity": "1/2", "unit": "cup"}]', '["Cook turkey with garlic, oregano, salt, and pepper until cooked through.", "Squeeze lemon juice over turkey while still hot; toss to coat.", "Prep vegetables: dice cucumber, halve tomatoes, slice olives.", "Separate lettuce leaves to use as wraps.", "Fill lettuce with warm turkey and vegetables.", "Top with feta and a drizzle of olive oil."]', 30, 4, 12.00, 'Season the turkey with lemon and oregano while still hot so the spices bloom into the meat.', 'Inspired by healthy restaurant tradition', TRUE),
  ('admin', NULL, 'LongHorn Parmesan Crusted Chicken', 'steakhouse', 'Juicy chicken topped with a golden parmesan crust creates a restaurant-style meal families love.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "parmesan cheese grated", "quantity": "1", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1/2", "unit": "cup"}, {"name": "mayonnaise", "quantity": "1/3", "unit": "cup"}, {"name": "provolone cheese slices", "quantity": "4", "unit": ""}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "onion powder", "quantity": "1/2", "unit": "tsp"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}]', '["Preheat oven to 400F. Season chicken with salt and pepper.", "Sear chicken in oil 3-4 minutes per side until golden.", "Place on sheet pan.", "Mix mayo, parmesan, panko, garlic powder, and onion powder.", "Spread parmesan crust mixture over each chicken breast.", "Top with provolone and bake 15-18 minutes until chicken is 165F and crust is golden."]', 40, 4, 18.00, 'Use real mayo as the binding agent — it creates a richer, more golden crust than egg wash.', 'Inspired by LongHorn Steakhouse', TRUE),
  ('admin', NULL, 'Cajun Blackened Fish Tacos', 'seafood', 'Flaky blackened fish tucked into tortillas with crunchy slaw creates a fresh dinner packed with flavor.', '[{"name": "tilapia or cod fillets", "quantity": "2", "unit": "lbs"}, {"name": "Cajun seasoning", "quantity": "3", "unit": "tbsp"}, {"name": "corn tortillas", "quantity": "8", "unit": ""}, {"name": "shredded cabbage", "quantity": "1", "unit": "bag"}, {"name": "sour cream", "quantity": "1/2", "unit": "cup"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "avocado", "quantity": "2", "unit": ""}, {"name": "butter", "quantity": "2", "unit": "tbsp"}]', '["Pat fish dry and coat both sides generously with Cajun seasoning.", "Heat cast iron skillet until very hot; add butter.", "Cook fish 3-4 minutes per side until dark and flaky.", "Mix cabbage with sour cream and lime juice.", "Warm tortillas in dry skillet.", "Flake fish; assemble tacos with slaw and sliced avocado."]', 30, 4, 19.00, 'Cast iron is ideal for blackening — it holds high heat evenly for a proper crust.', 'Inspired by Bonefish Grill', TRUE),
  ('admin', NULL, 'French Herb Pork Tenderloin', 'french', 'Herb-crusted pork tenderloin roasted until juicy creates an elegant yet approachable family dinner.', '[{"name": "pork tenderloin", "quantity": "2", "unit": "lbs"}, {"name": "Dijon mustard", "quantity": "3", "unit": "tbsp"}, {"name": "fresh rosemary", "quantity": "2", "unit": "tbsp"}, {"name": "fresh thyme", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "baby carrots", "quantity": "1", "unit": "lb"}, {"name": "baby potatoes", "quantity": "1", "unit": "lb"}]', '["Preheat oven to 425F. Mince garlic with rosemary and thyme.", "Rub tenderloin with Dijon then press herb-garlic mixture all over.", "Sear tenderloin in oil in oven-safe skillet 3 minutes per side.", "Add carrots and potatoes around tenderloin.", "Roast 20-25 minutes until internal temp reaches 145F.", "Rest 5 minutes before slicing."]', 45, 4, 18.00, 'Sear the tenderloin on all sides before roasting — it seals in the juices beautifully.', 'Inspired by French countryside tradition', TRUE),
  ('admin', NULL, 'Diner Salisbury Steak', 'american', 'Savory beef patties covered in rich mushroom gravy deliver classic diner comfort.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "cremini mushrooms", "quantity": "8", "unit": "oz"}, {"name": "beef broth", "quantity": "2", "unit": "cups"}, {"name": "Worcestershire sauce", "quantity": "3", "unit": "tbsp"}, {"name": "yellow onion", "quantity": "1", "unit": ""}, {"name": "panko breadcrumbs", "quantity": "1/2", "unit": "cup"}, {"name": "egg", "quantity": "1", "unit": ""}, {"name": "flour", "quantity": "2", "unit": "tbsp"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Mix beef with breadcrumbs, egg, Worcestershire, garlic powder, salt, and pepper; form 5 oval patties.", "Sear patties in butter 4 minutes per side; remove.", "Cook sliced mushrooms and onion in same pan until golden.", "Whisk in flour, then broth; simmer 5 minutes until gravy thickens.", "Return patties to gravy; simmer 10 minutes.", "Serve over mashed potatoes or rice."]', 45, 5, 17.00, 'Deglaze the pan with beef broth before adding onions to build a deeper gravy base.', 'Inspired by Denny''s dinner menu', TRUE),
  ('admin', NULL, 'Baked Ravioli Casserole', 'italian', 'Cheese ravioli layered with marinara and mozzarella creates a simple crowd-pleasing dinner.', '[{"name": "frozen cheese ravioli", "quantity": "25", "unit": "oz"}, {"name": "marinara sauce", "quantity": "48", "unit": "oz"}, {"name": "ground beef or Italian sausage", "quantity": "1", "unit": "lb"}, {"name": "shredded mozzarella", "quantity": "3", "unit": "cups"}, {"name": "parmesan cheese", "quantity": "1/2", "unit": "cup"}, {"name": "Italian seasoning", "quantity": "2", "unit": "tsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Preheat oven to 375F.", "Brown meat with Italian seasoning and garlic powder; drain fat.", "Spread 1 cup marinara in 9x13 baking dish.", "Layer half the frozen ravioli, half the meat, and half remaining sauce.", "Repeat layers; top with mozzarella and parmesan.", "Cover and bake 45 minutes; uncover last 10 minutes until bubbly."]', 40, 5, 17.00, 'No need to boil ravioli first — they cook through beautifully in the oven with the sauce.', 'Inspired by Fazoli''s', TRUE),
  ('admin', NULL, 'Steak and Cheese Quesadillas', 'mexican', 'Tender steak and melted cheese folded into crispy tortillas. Great with salsa and sour cream.', '[{"name": "sirloin or skirt steak", "quantity": "1.5", "unit": "lbs"}, {"name": "large flour tortillas", "quantity": "4", "unit": ""}, {"name": "Monterey Jack cheese shredded", "quantity": "2", "unit": "cups"}, {"name": "bell peppers", "quantity": "2", "unit": ""}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "fajita seasoning", "quantity": "2", "unit": "tbsp"}, {"name": "butter", "quantity": "2", "unit": "tbsp"}, {"name": "sour cream", "quantity": "1", "unit": "cup"}, {"name": "salsa", "quantity": "1", "unit": "cup"}]', '["Season steak with fajita seasoning; sear in skillet 3-4 minutes per side.", "Rest steak 5 minutes then slice thin.", "Saute sliced peppers and onion until softened.", "Lay tortilla in buttered skillet; add cheese, steak, and peppers on half.", "Fold and cook 2-3 minutes per side until golden and cheese melts.", "Slice and serve with sour cream and salsa."]', 30, 4, 19.00, 'Rest steak 5 minutes before slicing and cutting into small pieces for easier quesadilla filling.', 'Inspired by Chili''s', TRUE),
  ('admin', NULL, 'Korean Beef Lettuce Wraps', 'korean', 'Sweet savory beef wrapped in crisp lettuce delivers big flavor with fresh crunch.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "butter or Boston lettuce", "quantity": "2", "unit": "heads"}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "sesame oil", "quantity": "2", "unit": "tsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tsp"}, {"name": "brown sugar", "quantity": "2", "unit": "tbsp"}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "sesame seeds", "quantity": "1", "unit": "tbsp"}]', '["Cook rice according to package.", "Brown beef with garlic and ginger over medium-high heat.", "Add soy sauce, brown sugar, and sesame oil; cook 2 minutes.", "Separate lettuce leaves into cups.", "Serve rice and beef in lettuce cups.", "Top with green onions, sesame seeds, and drizzle of sesame oil."]', 25, 4, 16.00, 'Add a drizzle of sesame oil right before serving — it lifts all the other flavors.', 'Inspired by Korean BBQ tradition', TRUE),
  ('admin', NULL, 'Mediterranean Baked Feta Pasta', 'mediterranean', 'Roasted tomatoes and creamy feta melt into a silky sauce that coats pasta beautifully.', '[{"name": "penne or rigatoni pasta", "quantity": "1", "unit": "lb"}, {"name": "cherry tomatoes", "quantity": "2", "unit": "pints"}, {"name": "block feta cheese", "quantity": "8", "unit": "oz"}, {"name": "garlic", "quantity": "6", "unit": "cloves"}, {"name": "olive oil", "quantity": "1/3", "unit": "cup"}, {"name": "fresh basil", "quantity": "1", "unit": "cup"}, {"name": "red pepper flakes", "quantity": "1/2", "unit": "tsp"}, {"name": "salt and black pepper", "quantity": "", "unit": "to taste"}]', '["Preheat oven to 400F.", "Pour tomatoes into 9x13 baking dish; nestle feta block in center.", "Tuck garlic cloves around tomatoes; drizzle everything with olive oil.", "Season with red pepper flakes, salt, and pepper.", "Roast 35-40 minutes until tomatoes burst and feta is golden.", "Cook pasta; drain with 1 cup pasta water. Mash feta and tomatoes into sauce; toss with pasta and basil."]', 40, 5, 14.00, 'Use block feta not crumbles — it melts creamier in the oven.', 'Inspired by Greek taverna tradition', TRUE),
  ('admin', NULL, 'Southern Chicken and Rice Casserole', 'southern', 'Creamy chicken and rice baked until golden creates a timeless comfort-food dinner.', '[{"name": "chicken breasts or thighs", "quantity": "2", "unit": "lbs"}, {"name": "long grain white rice", "quantity": "2", "unit": "cups"}, {"name": "cream of chicken soup", "quantity": "2", "unit": "cans"}, {"name": "chicken broth", "quantity": "2", "unit": "cups"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Preheat oven to 350F.", "Mix soup, broth, diced onion, garlic powder, salt, and pepper.", "Pour raw rice into greased 9x13 baking dish.", "Pour soup mixture over rice; stir to combine.", "Lay chicken pieces on top; season generously.", "Cover with foil and bake 1 hour; uncover last 15 minutes until chicken is golden."]', 50, 6, 19.00, 'Use raw rice — it absorbs the broth while baking and becomes perfectly fluffy.', 'Inspired by Cracker Barrel', TRUE),
  ('admin', NULL, 'Thai Sweet Chili Chicken Rice Bowls', 'thai', 'Sweet chili glazed chicken served over fluffy rice with crisp vegetables. A perfect balance of sweet, savory, and fresh.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "sweet chili sauce", "quantity": "1/2", "unit": "cup"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "shredded carrots", "quantity": "2", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "soy sauce", "quantity": "2", "unit": "tbsp"}, {"name": "lime", "quantity": "1", "unit": ""}, {"name": "sesame seeds", "quantity": "1", "unit": "tbsp"}]', '["Cook rice according to package.", "Steam broccoli until tender-crisp.", "Cook chicken in skillet over medium-high heat 6-7 minutes per side.", "Combine sweet chili sauce and soy sauce; pour over chicken in last 3 minutes.", "Slice chicken.", "Assemble bowls with rice, chicken, broccoli, and carrots; garnish with sesame seeds and lime."]', 30, 4, 15.00, 'Add a squeeze of lime and fresh cilantro at the end for brightness against the sweet sauce.', 'Inspired by Thai street food tradition', TRUE),
  ('admin', NULL, 'Mediterranean Salmon Power Bowls', 'healthy', 'Roasted salmon, cucumbers, tomatoes, and lemon rice create a wholesome dinner that feels restaurant fresh.', '[{"name": "salmon fillets", "quantity": "2", "unit": "lbs"}, {"name": "quinoa or jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "cucumber sliced", "quantity": "1", "unit": ""}, {"name": "cherry tomatoes halved", "quantity": "1", "unit": "pint"}, {"name": "kalamata olives", "quantity": "1/2", "unit": "cup"}, {"name": "feta cheese", "quantity": "1/2", "unit": "cup"}, {"name": "lemon", "quantity": "2", "unit": ""}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "fresh dill", "quantity": "2", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}]', '["Cook quinoa or rice; fluff with lemon juice and olive oil.", "Season salmon with olive oil, garlic powder, salt, and pepper.", "Roast salmon at 400F for 15-18 minutes until flaky.", "Prepare toppings: slice cucumber, halve tomatoes, crumble feta.", "Assemble bowls with grain base, roasted salmon, and all toppings.", "Finish with fresh dill and lemon wedges."]', 35, 4, 23.00, 'Season salmon simply with olive oil, salt, and lemon — the fresh toppings do the work.', 'Inspired by Sweetgreen', TRUE),
  ('admin', NULL, 'Ruth''s Chris Garlic Butter Chicken', 'steakhouse', 'Tender chicken breasts finished with rich garlic butter bring steakhouse flavor to an affordable weeknight dinner.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "5", "unit": "tbsp"}, {"name": "garlic minced", "quantity": "6", "unit": "cloves"}, {"name": "fresh thyme", "quantity": "1", "unit": "tbsp"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "chicken broth", "quantity": "1/2", "unit": "cup"}, {"name": "heavy cream", "quantity": "1/4", "unit": "cup"}, {"name": "shallots", "quantity": "2", "unit": ""}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}]', '["Season chicken and sear in oil over medium-high heat 5-6 minutes per side.", "Remove chicken; saute shallots and garlic in butter until fragrant.", "Add broth and reduce by half.", "Stir in cream and thyme; simmer 2 minutes.", "Return chicken; baste with garlic butter repeatedly over 3 minutes.", "Serve with squeeze of lemon."]', 35, 4, 18.00, 'Baste the chicken with garlic butter every 2 minutes for a rich caramelized finish.', 'Inspired by Ruth''s Chris', TRUE),
  ('admin', NULL, 'Shrimp Scampi Linguine', 'seafood', 'Garlic butter shrimp tossed with linguine creates a restaurant classic that''s surprisingly easy to make at home.', '[{"name": "large shrimp peeled deveined", "quantity": "1.5", "unit": "lbs"}, {"name": "linguine pasta", "quantity": "1", "unit": "lb"}, {"name": "butter", "quantity": "5", "unit": "tbsp"}, {"name": "garlic", "quantity": "6", "unit": "cloves"}, {"name": "dry white wine or chicken broth", "quantity": "1/2", "unit": "cup"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "fresh parsley", "quantity": "1/3", "unit": "cup"}, {"name": "red pepper flakes", "quantity": "1/2", "unit": "tsp"}, {"name": "parmesan optional", "quantity": "1/4", "unit": "cup"}]', '["Cook linguine until al dente; reserve 1 cup pasta water; drain.", "Saute garlic and red pepper flakes in butter 1 minute.", "Add shrimp; cook 2 minutes per side until pink; remove shrimp.", "Pour wine into pan; scrape browned bits; reduce 2 minutes.", "Add pasta and pasta water; toss to coat with sauce.", "Return shrimp; toss with parsley and lemon juice; serve."]', 30, 4, 21.00, 'Use the shrimp shells to make a quick butter sauce base before adding clean shrimp.', 'Inspired by Red Lobster', TRUE),
  ('admin', NULL, 'French Country Beef Stew', 'french', 'Tender beef simmered with vegetables in a rich broth creates a comforting family dinner.', '[{"name": "beef chuck cubed", "quantity": "2", "unit": "lbs"}, {"name": "beef broth or red wine", "quantity": "2", "unit": "cups"}, {"name": "Yukon gold potatoes", "quantity": "1.5", "unit": "lbs"}, {"name": "carrots", "quantity": "3", "unit": ""}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh thyme", "quantity": "2", "unit": "sprigs"}, {"name": "tomato paste", "quantity": "2", "unit": "tbsp"}, {"name": "flour", "quantity": "3", "unit": "tbsp"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}]', '["Season beef cubes and brown in batches in butter over high heat; remove.", "Saute onion, carrots, and garlic in same pot.", "Stir in flour and tomato paste; cook 1 minute.", "Add broth and thyme; return beef and bring to simmer.", "Cover and cook 40 minutes until beef is tender.", "Add potatoes for final 20 minutes until cooked through."]', 60, 6, 24.00, 'Brown beef in batches without crowding — proper searing builds the deep stew flavor.', 'Inspired by French countryside tradition', TRUE),
  ('admin', NULL, 'Bacon BBQ Cheeseburger Bowls', 'american', 'Everything you love about a bacon cheeseburger served in a hearty rice bowl. Smoky, cheesy, and loaded with flavor.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "bacon strips", "quantity": "6", "unit": ""}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "shredded cheddar cheese", "quantity": "1.5", "unit": "cups"}, {"name": "BBQ sauce", "quantity": "1/3", "unit": "cup"}, {"name": "dill pickles sliced", "quantity": "1/2", "unit": "cup"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "shredded lettuce", "quantity": "2", "unit": "cups"}, {"name": "tomato diced", "quantity": "2", "unit": ""}]', '["Cook rice according to package.", "Cook bacon until crispy; crumble.", "Brown beef with diced onion; season with salt and pepper; drain fat.", "Stir BBQ sauce into beef.", "Assemble bowls with rice, BBQ beef, and shredded cheese.", "Top with bacon, lettuce, tomato, pickles, and extra BBQ sauce."]', 30, 5, 17.00, 'Add a drizzle of BBQ sauce and a pickle slice on each bowl for the full burger experience.', 'Inspired by Five Guys', TRUE),
  ('admin', NULL, 'Tuscan Chicken Gnocchi Skillet', 'italian', 'Pillowy gnocchi tossed with creamy sauce, chicken, and spinach. Restaurant flavor without the restaurant bill.', '[{"name": "chicken breasts", "quantity": "1.5", "unit": "lbs"}, {"name": "potato gnocchi", "quantity": "16", "unit": "oz"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "baby spinach", "quantity": "3", "unit": "cups"}, {"name": "sun-dried tomatoes", "quantity": "1/3", "unit": "cup"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "parmesan cheese", "quantity": "3/4", "unit": "cup"}, {"name": "Italian seasoning", "quantity": "1", "unit": "tsp"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "chicken broth", "quantity": "1/2", "unit": "cup"}]', '["Cook chicken in butter 5-6 minutes per side; remove and slice.", "In same pan, cook gnocchi until golden on one side, about 3 minutes; remove.", "Saute garlic and sun-dried tomatoes; add broth and cream.", "Stir in parmesan and Italian seasoning; simmer until thickened.", "Add spinach, gnocchi, and sliced chicken; toss to coat.", "Serve immediately with extra parmesan."]', 40, 5, 19.00, 'Pan-fry gnocchi until golden before adding the sauce for a better texture.', 'Inspired by Olive Garden', TRUE),
  ('admin', NULL, 'Street Corn Chicken Tacos', 'mexican', 'Grilled chicken topped with creamy street corn filling creates taco night perfection.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "corn kernels fresh or frozen", "quantity": "2", "unit": "cups"}, {"name": "flour tortillas", "quantity": "8", "unit": ""}, {"name": "mayo", "quantity": "3", "unit": "tbsp"}, {"name": "cotija or feta cheese", "quantity": "1/2", "unit": "cup"}, {"name": "chili powder", "quantity": "2", "unit": "tsp"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "cilantro", "quantity": "1/4", "unit": "cup"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "jalape\u00f1o optional", "quantity": "1", "unit": ""}]', '["Season chicken with chili powder, garlic powder, salt, and cook in skillet 6-7 minutes per side.", "Char corn in dry skillet over high heat 3 minutes until slightly blackened.", "Mix charred corn with mayo, half the cotija, lime juice, and chili powder.", "Slice chicken thinly.", "Warm tortillas.", "Assemble tacos with chicken, street corn mixture, cotija, and cilantro."]', 30, 4, 15.00, 'Char the corn in a dry skillet for 3 minutes to get smoky flavor without a grill.', 'Inspired by Chipotle', TRUE),
  ('admin', NULL, 'Japanese Beef Fried Rice', 'japanese', 'Savory beef, vegetables, and rice stir-fried together create a complete meal in one pan.', '[{"name": "ground beef or flank steak strips", "quantity": "1.5", "unit": "lbs"}, {"name": "day-old jasmine rice", "quantity": "4", "unit": "cups"}, {"name": "eggs", "quantity": "3", "unit": ""}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "oyster sauce", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tsp"}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "frozen peas and carrots", "quantity": "1", "unit": "cup"}, {"name": "sesame oil", "quantity": "1", "unit": "tbsp"}, {"name": "vegetable oil", "quantity": "3", "unit": "tbsp"}]', '["Scramble eggs in oil in hot wok or skillet; remove.", "Add more oil; stir fry beef with garlic and ginger over high heat until browned.", "Add peas and carrots; stir fry 2 minutes.", "Push everything to edges; add rice to center and press down 1 minute.", "Add soy sauce and oyster sauce; toss everything together.", "Return eggs; finish with sesame oil and green onions."]', 25, 4, 17.00, 'Day-old cold rice fries much better than fresh rice — plan ahead or spread fresh rice to cool.', 'Inspired by Benihana', TRUE),
  ('admin', NULL, 'Greek Chicken Lemon Soup', 'greek', 'Tender chicken, rice, and lemon create a bright comforting soup that''s both hearty and refreshing.', '[{"name": "chicken breasts or thighs", "quantity": "2", "unit": "lbs"}, {"name": "long grain rice", "quantity": "3/4", "unit": "cup"}, {"name": "chicken broth", "quantity": "8", "unit": "cups"}, {"name": "lemon juice and zest", "quantity": "2", "unit": "lemons"}, {"name": "eggs", "quantity": "3", "unit": ""}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "carrots", "quantity": "2", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "fresh dill", "quantity": "2", "unit": "tbsp"}]', '["Simmer chicken in broth with onion, carrots, and garlic 20 minutes.", "Remove chicken; shred and set aside.", "Add rice to simmering broth; cook 15 minutes.", "Whisk eggs with lemon juice in a bowl.", "Slowly ladle 2 cups of hot broth into egg mixture while whisking constantly.", "Pour tempered eggs back into pot; stir in shredded chicken and dill; do not boil."]', 45, 5, 16.00, 'Temper eggs by adding hot broth slowly — this prevents scrambled eggs in your soup.', 'Inspired by Greek taverna tradition', TRUE),
  ('admin', NULL, 'Pulled Pork Mac and Cheese Bake', 'bbq', 'Smoky pulled pork layered over creamy mac and cheese creates the ultimate comfort-food casserole.', '[{"name": "pulled pork store-bought", "quantity": "1", "unit": "lb"}, {"name": "elbow pasta", "quantity": "1", "unit": "lb"}, {"name": "sharp cheddar cheese shredded", "quantity": "3", "unit": "cups"}, {"name": "milk", "quantity": "2", "unit": "cups"}, {"name": "butter", "quantity": "4", "unit": "tbsp"}, {"name": "flour", "quantity": "3", "unit": "tbsp"}, {"name": "BBQ sauce", "quantity": "1/3", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1", "unit": "cup"}, {"name": "onion powder", "quantity": "1", "unit": "tsp"}]', '["Cook pasta until al dente; drain.", "Melt butter; whisk in flour and cook 1 minute.", "Add milk gradually, stirring until smooth and thick.", "Stir in cheddar and onion powder until melted.", "Fold pasta into cheese sauce; spread in baking dish.", "Top with pulled pork, drizzle BBQ sauce, sprinkle panko; bake at 375F for 25 minutes."]', 50, 6, 22.50, 'Add a layer of panko on top before baking for a crunchy golden crust.', 'Inspired by BBQ tradition', TRUE),
  ('admin', NULL, 'Chicken Tikka Rice Skillet', 'indian', 'Mild tikka-spiced chicken simmered with rice creates a one-pan dinner full of warming flavors.', '[{"name": "chicken thighs diced", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "crushed tomatoes", "quantity": "14", "unit": "oz can"}, {"name": "heavy cream", "quantity": "1/2", "unit": "cup"}, {"name": "butter", "quantity": "3", "unit": "tbsp"}, {"name": "tikka masala spice blend", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "chicken broth", "quantity": "2", "unit": "cups"}]', '["Saute diced onion in butter until soft, about 5 minutes.", "Add garlic, ginger, and tikka spice; stir 1 minute until fragrant.", "Add diced chicken and cook 5 minutes.", "Stir in crushed tomatoes, broth, and rice; bring to boil.", "Cover and simmer 18-20 minutes until rice absorbs broth.", "Stir in cream and serve."]', 35, 4, 15.00, 'Toast tikka spices in butter for 30 seconds before adding liquid to awaken their aroma.', 'Inspired by Indian dhaba tradition', TRUE),
  ('admin', NULL, 'Turkey Veggie Stir Fry', 'healthy', 'Lean turkey and colorful vegetables come together in a quick skillet dinner packed with protein.', '[{"name": "ground turkey", "quantity": "1.5", "unit": "lbs"}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "bell peppers", "quantity": "2", "unit": ""}, {"name": "snap peas", "quantity": "1", "unit": "cup"}, {"name": "shredded carrots", "quantity": "2", "unit": ""}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "sesame oil", "quantity": "1", "unit": "tbsp"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "green onions", "quantity": "3", "unit": ""}]', '["Cook rice according to package.", "Brown turkey with garlic and ginger in large skillet over high heat.", "Push turkey to edges; add broccoli and peppers to center.", "Cook vegetables 3-4 minutes until tender-crisp.", "Add snap peas and carrots; stir fry 1 minute.", "Toss everything with soy sauce and sesame oil; serve over rice garnished with green onions."]', 25, 4, 12.00, 'Add vegetables in order of cook time — hard ones first, tender leafy greens last.', 'Inspired by healthy restaurant tradition', TRUE),
  ('admin', NULL, 'Outback Alice Springs Chicken Bake', 'steakhouse', 'Chicken topped with bacon, mushrooms, and melted cheese recreates one of Outback''s most famous dishes.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "bacon strips", "quantity": "8", "unit": ""}, {"name": "cremini mushrooms", "quantity": "8", "unit": "oz"}, {"name": "shredded Monterey Jack and cheddar", "quantity": "2", "unit": "cups"}, {"name": "honey", "quantity": "3", "unit": "tbsp"}, {"name": "Dijon mustard", "quantity": "3", "unit": "tbsp"}, {"name": "mayo", "quantity": "2", "unit": "tbsp"}, {"name": "garlic powder", "quantity": "1", "unit": "tsp"}, {"name": "olive oil", "quantity": "2", "unit": "tbsp"}]', '["Preheat oven to 400F. Whisk honey, Dijon, and mayo for honey mustard sauce.", "Cook bacon until crispy; crumble. Saute sliced mushrooms.", "Sear chicken in oil 3-4 minutes per side.", "Spread honey mustard sauce over each chicken breast.", "Top with mushrooms, bacon, and shredded cheese.", "Bake 20-22 minutes until chicken is 165F and cheese is bubbly."]', 45, 4, 19.00, 'Make the honey mustard sauce ahead — it doubles as a great dipping sauce on the side.', 'Inspired by Outback Steakhouse', TRUE),
  ('admin', NULL, 'Garlic Parmesan Fish and Potatoes', 'seafood', 'Flaky white fish and roasted potatoes tossed with garlic parmesan create a simple but elegant dinner.', '[{"name": "tilapia or cod fillets", "quantity": "2", "unit": "lbs"}, {"name": "baby potatoes halved", "quantity": "1.5", "unit": "lbs"}, {"name": "parmesan cheese grated", "quantity": "1", "unit": "cup"}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "olive oil", "quantity": "4", "unit": "tbsp"}, {"name": "panko breadcrumbs", "quantity": "1/2", "unit": "cup"}, {"name": "fresh parsley", "quantity": "1/4", "unit": "cup"}, {"name": "lemon", "quantity": "1", "unit": ""}]', '["Preheat oven to 425F.", "Toss halved potatoes with oil, garlic, salt, and pepper; roast 20 minutes.", "Mix parmesan with panko, remaining garlic, and 2 tbsp oil.", "Place fish beside potatoes; press parmesan crust onto each fillet.", "Roast 12-15 minutes until fish flakes and crust is golden.", "Garnish with parsley and lemon wedges."]', 35, 4, 20.00, 'Add parmesan to potatoes in the last 5 minutes so it crisps without burning.', 'Inspired by McCormick and Schmick''s', TRUE),
  ('admin', NULL, 'Chicken Provencal Skillet', 'french', 'Tomatoes, herbs, and tender chicken create a rustic French-inspired dinner. Fresh flavors shine together beautifully.', '[{"name": "bone-in chicken thighs", "quantity": "2", "unit": "lbs"}, {"name": "cherry tomatoes", "quantity": "2", "unit": "pints"}, {"name": "kalamata olives", "quantity": "1/2", "unit": "cup"}, {"name": "capers", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "herbes de Provence", "quantity": "2", "unit": "tsp"}, {"name": "white wine or chicken broth", "quantity": "1/2", "unit": "cup"}, {"name": "olive oil", "quantity": "3", "unit": "tbsp"}, {"name": "fresh thyme", "quantity": "4", "unit": "sprigs"}]', '["Season chicken and sear skin-side down in oil 6 minutes until golden; flip 3 minutes.", "Remove chicken; add garlic to pan and saute 30 seconds.", "Add wine and scrape browned bits.", "Add tomatoes, olives, capers, herbes de Provence, and thyme.", "Return chicken skin-side up; cover and simmer 20 minutes.", "Serve with crusty bread."]', 40, 4, 16.00, 'Use a lid to trap steam and finish cooking chicken gently in the tomato broth.', 'Inspired by French bistro tradition', TRUE),
  ('admin', NULL, 'Bacon Ranch Chicken Pasta', 'american', 'Creamy ranch sauce, bacon, and chicken coat pasta in every bite. A guaranteed family favorite.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "penne pasta", "quantity": "1", "unit": "lb"}, {"name": "bacon strips", "quantity": "8", "unit": ""}, {"name": "ranch dressing", "quantity": "1/2", "unit": "cup"}, {"name": "heavy cream", "quantity": "1", "unit": "cup"}, {"name": "shredded cheddar cheese", "quantity": "1", "unit": "cup"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "butter", "quantity": "2", "unit": "tbsp"}]', '["Cook pasta until al dente; drain.", "Cook bacon until crispy; crumble. Reserve 1 tbsp drippings.", "Cook chicken in butter and drippings 5-6 minutes per side; slice.", "Saute garlic in same pan; add cream and simmer until slightly thickened.", "Remove from heat; stir in ranch dressing and cheddar.", "Toss pasta with sauce, chicken, and bacon; garnish with green onions."]', 30, 5, 17.00, 'Add ranch dressing at the very end off heat — cooking it kills the tangy brightness.', 'Inspired by TGI Fridays', TRUE),
  ('admin', NULL, 'Baked Meatball Parmesan Subs', 'italian', 'Juicy meatballs, marinara, and melted mozzarella stuffed into toasted rolls. Messy in the best possible way.', '[{"name": "ground beef", "quantity": "2", "unit": "lbs"}, {"name": "hoagie or sub rolls", "quantity": "5", "unit": ""}, {"name": "marinara sauce", "quantity": "24", "unit": "oz"}, {"name": "shredded mozzarella", "quantity": "2", "unit": "cups"}, {"name": "parmesan cheese", "quantity": "1/2", "unit": "cup"}, {"name": "panko breadcrumbs", "quantity": "1/2", "unit": "cup"}, {"name": "eggs", "quantity": "2", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "Italian seasoning", "quantity": "2", "unit": "tsp"}]', '["Preheat oven to 400F.", "Mix beef with breadcrumbs, eggs, minced garlic, Italian seasoning, salt, and pepper; form 20 meatballs.", "Bake meatballs 18 minutes.", "Simmer meatballs in marinara sauce 10 minutes.", "Split and toast hoagie rolls.", "Fill rolls with meatballs and sauce; top with mozzarella and parmesan; broil 2-3 minutes until bubbly."]', 40, 5, 17.50, 'Simmer meatballs in marinara for 10 minutes before stuffing — they absorb flavor and stay juicy.', 'Inspired by Fazoli''s', TRUE),
  ('admin', NULL, 'Steak Burrito Bowls', 'mexican', 'Tender steak, rice, beans, and toppings create a customizable dinner packed with flavor.', '[{"name": "flank or skirt steak", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "canned black beans", "quantity": "1", "unit": "can"}, {"name": "frozen corn", "quantity": "1", "unit": "cup"}, {"name": "bell peppers", "quantity": "2", "unit": ""}, {"name": "fajita seasoning", "quantity": "3", "unit": "tbsp"}, {"name": "lime", "quantity": "2", "unit": ""}, {"name": "sour cream", "quantity": "1", "unit": "cup"}, {"name": "shredded cheddar", "quantity": "1", "unit": "cup"}]', '["Season steak with fajita seasoning; marinate 20 minutes if time allows.", "Cook steak over high heat 4-5 minutes per side; rest 5 minutes; slice against grain.", "Cook rice; fluff with lime juice.", "Warm beans and corn; saute peppers until slightly charred.", "Assemble bowls with rice, sliced steak, beans, corn, and peppers.", "Top with sour cream, cheddar, and lime."]', 35, 4, 20.00, 'Marinate steak in lime juice, garlic, and cumin for even 20 minutes for noticeably better flavor.', 'Inspired by Chipotle', TRUE),
  ('admin', NULL, 'Korean BBQ Chicken Rice Bowls', 'korean', 'Sweet and savory chicken glazed in Korean-style sauce creates a satisfying rice bowl dinner.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "jasmine rice", "quantity": "2", "unit": "cups"}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "brown sugar", "quantity": "3", "unit": "tbsp"}, {"name": "sesame oil", "quantity": "2", "unit": "tsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tbsp"}, {"name": "gochujang or chili paste", "quantity": "1", "unit": "tbsp"}, {"name": "cucumber sliced", "quantity": "1", "unit": ""}, {"name": "shredded carrots", "quantity": "2", "unit": ""}, {"name": "sesame seeds", "quantity": "1", "unit": "tbsp"}, {"name": "green onions", "quantity": "3", "unit": ""}]', '["Cook rice according to package.", "Whisk soy sauce, sugar, sesame oil, garlic, ginger, and gochujang.", "Cook chicken in skillet over medium-high heat 6-7 minutes per side.", "Pour sauce over chicken and cook 2-3 minutes until caramelized.", "Slice chicken.", "Assemble bowls with rice, chicken, cucumber, and carrots; garnish with sesame seeds and green onions."]', 30, 4, 15.00, 'Let chicken caramelize without stirring for the last 2 minutes for glossy glazed edges.', 'Inspired by Korean BBQ tradition', TRUE),
  ('admin', NULL, 'Mediterranean Vegetable Pasta', 'mediterranean', 'Roasted vegetables tossed with pasta, olive oil, and feta. Fresh, simple, and satisfying.', '[{"name": "penne pasta", "quantity": "1", "unit": "lb"}, {"name": "zucchini", "quantity": "2", "unit": ""}, {"name": "bell peppers", "quantity": "2", "unit": ""}, {"name": "cherry tomatoes", "quantity": "1", "unit": "pint"}, {"name": "baby spinach", "quantity": "3", "unit": "cups"}, {"name": "feta cheese crumbled", "quantity": "3/4", "unit": "cup"}, {"name": "garlic", "quantity": "5", "unit": "cloves"}, {"name": "olive oil", "quantity": "1/3", "unit": "cup"}, {"name": "fresh basil", "quantity": "1/2", "unit": "cup"}, {"name": "kalamata olives", "quantity": "1/2", "unit": "cup"}, {"name": "red pepper flakes", "quantity": "1/2", "unit": "tsp"}]', '["Preheat oven to 425F.", "Chop zucchini and peppers; toss with oil, garlic, salt, and pepper.", "Roast vegetables 20 minutes; add tomatoes last 10 minutes.", "Cook pasta; reserve 1 cup pasta water; drain.", "Toss hot pasta with roasted vegetables, spinach, olives, and pasta water.", "Fold in feta, basil, and red pepper flakes; serve."]', 40, 5, 14.00, 'Save a cup of pasta water to emulsify the olive oil and feta into a light creamy sauce.', 'Inspired by Mediterranean tradition', TRUE),
  ('admin', NULL, 'Southern Beef and Rice Skillet', 'southern', 'Ground beef, rice, and vegetables simmer into a hearty family dinner. Simple comfort food.', '[{"name": "ground beef", "quantity": "1.5", "unit": "lbs"}, {"name": "long grain rice", "quantity": "2", "unit": "cups"}, {"name": "diced canned tomatoes", "quantity": "14", "unit": "oz can"}, {"name": "chicken broth", "quantity": "3", "unit": "cups"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "Worcestershire sauce", "quantity": "2", "unit": "tbsp"}, {"name": "shredded cheddar cheese", "quantity": "1", "unit": "cup"}, {"name": "frozen green beans", "quantity": "1", "unit": "cup"}, {"name": "smoked paprika", "quantity": "1", "unit": "tsp"}]', '["Brown beef with diced onion and garlic; drain fat.", "Stir in Worcestershire, paprika, tomatoes, and broth.", "Add rice; bring to boil then cover and simmer 18 minutes.", "Stir in green beans; cook 5 more minutes covered.", "Fluff rice and stir in cheddar cheese.", "Serve hot directly from skillet."]', 35, 5, 16.00, 'Add Worcestershire sauce and a pinch of smoked paprika to deepen the beef flavor.', 'Inspired by Bob Evans', TRUE),
  ('admin', NULL, 'Thai Peanut Chicken Noodle Bowls', 'thai', 'Creamy peanut sauce coats noodles and chicken in a restaurant-inspired dinner that''s ready quickly.', '[{"name": "chicken thighs boneless", "quantity": "2", "unit": "lbs"}, {"name": "rice noodles or spaghetti", "quantity": "12", "unit": "oz"}, {"name": "peanut butter", "quantity": "1/3", "unit": "cup"}, {"name": "soy sauce", "quantity": "3", "unit": "tbsp"}, {"name": "honey", "quantity": "2", "unit": "tbsp"}, {"name": "lime juice", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "3", "unit": "cloves"}, {"name": "fresh ginger", "quantity": "1", "unit": "tsp"}, {"name": "shredded carrots", "quantity": "2", "unit": ""}, {"name": "green onions", "quantity": "4", "unit": ""}, {"name": "crushed peanuts optional", "quantity": "1/4", "unit": "cup"}]', '["Cook noodles; drain and rinse with cold water.", "Cook chicken in skillet 6-7 minutes per side; slice.", "Whisk peanut butter with soy sauce, honey, lime, garlic, and ginger; add warm water to reach sauce consistency.", "Toss noodles in peanut sauce.", "Top with sliced chicken, carrots, and green onions.", "Garnish with crushed peanuts."]', 30, 4, 15.00, 'Thin peanut sauce gradually with warm water until it coats a spoon — not too thick, not watery.', 'Inspired by Thai street food tradition', TRUE),
  ('admin', NULL, 'Garlic Herb Chicken Power Bowls', 'healthy', 'Seasoned chicken served with grains and vegetables creates a balanced dinner full of flavor and nutrition.', '[{"name": "chicken breasts", "quantity": "2", "unit": "lbs"}, {"name": "quinoa or brown rice", "quantity": "2", "unit": "cups"}, {"name": "sweet potato cubed", "quantity": "2", "unit": ""}, {"name": "broccoli florets", "quantity": "1", "unit": "head"}, {"name": "olive oil", "quantity": "4", "unit": "tbsp"}, {"name": "lemon", "quantity": "1", "unit": ""}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "dried thyme", "quantity": "1", "unit": "tsp"}, {"name": "baby spinach or kale", "quantity": "3", "unit": "cups"}, {"name": "salt and pepper", "quantity": "", "unit": "to taste"}]', '["Cook quinoa or rice according to package.", "Preheat oven to 425F.", "Toss sweet potato and broccoli with oil, garlic, thyme, salt, and pepper; roast 20 minutes.", "Season chicken with oil, thyme, garlic, salt, and pepper; roast alongside vegetables 22-25 minutes until 165F.", "Slice chicken.", "Assemble bowls with grains, spinach, roasted vegetables, and chicken; squeeze lemon over top."]', 30, 4, 14.00, 'Marinate chicken in olive oil, garlic, and herbs for even 15 minutes for noticeably more flavor.', 'Inspired by healthy restaurant tradition', TRUE),
  ('admin', NULL, 'Steakhouse Loaded Beef Tips', 'steakhouse', 'Tender beef tips simmered in savory gravy and served over mashed potatoes create a hearty finale to the collection.', '[{"name": "beef sirloin tips or cubed steak", "quantity": "2", "unit": "lbs"}, {"name": "beef broth", "quantity": "2", "unit": "cups"}, {"name": "cremini mushrooms", "quantity": "8", "unit": "oz"}, {"name": "russet potatoes", "quantity": "2", "unit": "lbs"}, {"name": "butter", "quantity": "5", "unit": "tbsp"}, {"name": "Worcestershire sauce", "quantity": "3", "unit": "tbsp"}, {"name": "cornstarch", "quantity": "2", "unit": "tbsp"}, {"name": "garlic", "quantity": "4", "unit": "cloves"}, {"name": "onion", "quantity": "1", "unit": ""}, {"name": "heavy cream", "quantity": "1/2", "unit": "cup"}]', '["Season beef tips and brown in batches in butter over high heat; remove.", "Saute sliced mushrooms and diced onion until golden.", "Add garlic; deglaze with broth, scraping browned bits.", "Stir in Worcestershire; simmer 5 minutes.", "Whisk cornstarch with 2 tbsp cold water; stir into broth and simmer until thickened.", "Return beef; simmer 20 minutes. Meanwhile boil and mash potatoes with butter and cream. Serve beef tips and gravy over mashed potatoes."]', 50, 5, 25.00, 'Deglaze the pan with beef broth after browning — those browned bits become the gravy.', 'Inspired by Texas Roadhouse', TRUE)
;

